def _load_broker(name: str) -> Any:
    return importlib.import_module(BROKER_MODULES[name])


def _env(key: str) -> str:
    return os.getenv(key, "").strip()


def _broker_has_creds(broker: str) -> bool:
    """Is there at least one usable login at this broker?

    Asks broker_logins rather than a fixed key list, so a broker configured
    only at login 2 (CHASE_USERNAME_2, nothing bare) still counts as linked.
    The old list could not see those keys at all, which would have shown a
    fully configured broker as "not connected".
    """
    if broker_logins.logins(broker):
        return True
    return any(_env(k) for k in BROKER_ENV_KEYS.get(broker, []))


def _public_token_indices() -> List[int]:
    """Indices of configured Public logins — one row each on the status card.

    No longer capped at three. A household running two people's accounts needs
    more than three Public logins, and the old `(1, 2, 3)` meant a fourth token
    could be saved and then read by nothing, which on screen is indistinguishable
    from a broken login.
    """
    return [login.idx for login in broker_logins.logins("public")]


def _broker_status_plan(linked: List[str], public_indices, evidence) -> List[tuple]:
    """(kind, key, label, status) for each Broker Status row, in display order.

    `public_indices` and `evidence` are called, not passed in evaluated, so a
    card with no Public login never asks for Public's token list.

    Public runs one independent login per API secret token — each configured
    token is its own P1/P2/P3 row so you can see which connects. Elsewhere only
    a count we have evidence for is shown; a broker nothing has reported on yet
    says so rather than showing a number.
    """
    rows: List[tuple] = []
    counts = None
    for broker in linked:
        if broker == "public":
            for idx in public_indices():
                rows.append(("public", idx, f"Public P{idx}", "credentials set"))
            continue
        if counts is None:
            counts = evidence() or {}
        n = counts.get(broker)
        rows.append(("broker", broker, broker.capitalize(),
                     _plural(n, "account") if n else "credentials set"))
    return rows


def _write_json(path: Path, data: Any, *, indent: int = 2) -> None:
    """Write one of the app's state files so a crash cannot leave it half-done.

    `write_text` truncates first and writes second. Force-quit the app, lose
    power, or fill the disk in between and the file is empty or cut in half —
    and every one of these files is read back with json.loads, which turns a
    truncated file into an exception and, in most of these call sites, into a
    silently empty state. An empty picks.json looks like "no plays today"; an
    empty mirror_state.json looks like a mirror that has never run.

    Same shape as trade_journal._save and lifecycle: a UNIQUE temp file beside
    the real one (a fixed `<file>.tmp` let two threads saving the same file
    collide, and one save vanished), fsync, then an atomic rename over it.
    """
    atomic.write_json(path, data, indent=indent)


def _env_quote(val: str) -> str:
    """One .env value, written so python-dotenv reads back exactly `val`.

    Unquoted was how a password got mangled: `abc #def` loads as `abc`, a
    leading space is stripped, and a value that starts with a quote is parsed
    as a quoted string. Single quotes with `\\` and `\\'` escaped survive all of
    that. (`${...}` inside one is still interpolated by python-dotenv, which is
    why every load in this app passes interpolate=False.)

    The one thing single quotes cannot hold is a TRAILING backslash: the
    parser reads `\\'` at the end as an escaped quote and runs on into the next
    line. Such a value is written bare when bare is safe, and refused when it
    is not, rather than corrupting every key after it.
    """
    val = str(val)
    if "\n" in val or "\r" in val:
        raise ValueError("a .env value cannot span lines")
    if not val.endswith("\\"):
        return "'" + val.replace("\\", "\\\\").replace("'", "\\'") + "'"
    bare_ok = (val == val.strip() and val[:1] not in ("'", '"')
               and not re.search(r"\s#", val))
    if bare_ok:
        return val
    raise ValueError("this value can't be stored in .env (it ends with a "
                     "backslash and has spaces or a ' #')")


def _save_env_file(updates: Dict[str, str]) -> None:
    """Write `updates` into .env, keeping every other line as it was.

    Comments, order and unrelated keys are untouched; a key that already
    exists is rewritten in place (every occurrence, so no stale duplicate
    later in the file wins the load). Written temp-then-rename like every
    other state file: this one holds the broker logins.
    """
    encoded = {key: _env_quote(val) for key, val in updates.items()}
    lines: List[str] = []
    if ENV_FILE.exists():
        lines = ENV_FILE.read_text(encoding="utf-8").splitlines()

    existing_keys: set = set()
    new_lines: List[str] = []
    for line in lines:
        m = re.match(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=", line)
        if m and m.group(1) in encoded:
            key = m.group(1)
            new_lines.append(f"{key}={encoded[key]}")
            existing_keys.add(key)
        else:
            new_lines.append(line)

    for key, val in encoded.items():
        if key not in existing_keys:
            new_lines.append(f"{key}={val}")

    tmp = ENV_FILE.with_name(ENV_FILE.name + ".tmp")
    tmp.write_text("\n".join(new_lines) + "\n", encoding="utf-8")
    atomic.replace(tmp, ENV_FILE)
    # Through broker_logins so a save cannot overwrite a key a login fan-out
    # has pointed elsewhere right now (see _reload_env).
    broker_logins.set_env(updates)


# ---------------------------------------------------------------------------
# Paint suspension — one clean frame per page swap
# ---------------------------------------------------------------------------
#
# Tk paints a freshly shown page from idle callbacks, one widget at a time, and
# CTk widgets paint in stages on top of that (the canvas first, then the
# rounded shapes). On a page of a few hundred widgets you can watch the boxes
# arrive. Win32 has a switch for exactly this: WM_SETREDRAW(FALSE) on a window
# stops it and its children from reaching the screen, and turning it back on
# plus a RedrawWindow puts the finished result up in one go.
#
# Everything here fails open. If user32 is missing (not Windows) or a call
# raises, painting simply is not suspended — the page still appears, it just
# assembles in view the way it always did. The one outcome that must never
# happen is a window left with redraw OFF, which looks like a frozen, blank
# app; hence the depth count (nested freezes re-enable only at the outermost)
# and the unconditional `finally`.

_WM_SETREDRAW = 0x000B
_RDW_INVALIDATE = 0x0001
_RDW_ERASE = 0x0004
_RDW_ALLCHILDREN = 0x0080
_RDW_UPDATENOW = 0x0100
_RDW_FRAME = 0x0400
_REDRAW_FLAGS = (_RDW_ERASE | _RDW_FRAME | _RDW_INVALIDATE
                 | _RDW_ALLCHILDREN | _RDW_UPDATENOW)


def _load_user32():
    if sys.platform != "win32":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        u = ctypes.WinDLL("user32", use_last_error=True)
        u.SendMessageW.argtypes = [wintypes.HWND, wintypes.UINT,
                                   wintypes.WPARAM, wintypes.LPARAM]
        u.SendMessageW.restype = wintypes.LPARAM
        u.RedrawWindow.argtypes = [wintypes.HWND, ctypes.c_void_p,
                                   ctypes.c_void_p, wintypes.UINT]
        u.RedrawWindow.restype = wintypes.BOOL
        return u
    except Exception:
        return None


# Module-level so tests can swap in a recorder; None means "no suspension".
_USER32 = _load_user32()
_freeze_depth: Dict[int, int] = {}

#: Page swaps repaint just the header and the raised page (see _raise_page)
#: instead of everything under the content area. OFF until it has been looked
#: at on the target machine. The baseline is ~75ms per switch; the sandbox
#: run meant to measure this one ran with the display asleep (no painting, so
#: no valid timing and no screenshots), and a repaint that is too narrow shows
#: up as stale pixels, not as an error. Flip to True and look before keeping.
_RAISE_SCOPED = False


def _is_ctk(w) -> bool:
    """A CustomTkinter widget (or subclass, like RoundedFrame / PillButton)."""
    return any(c.__module__.startswith("customtkinter") for c in type(w).__mro__)


class _frozen:
    """`with _frozen(widget): ...` — nothing under `widget` reaches the screen
    until the block ends, then it all appears at once.

    Always pair the body with an update_idletasks() before leaving it when the
    point is to hide assembly: Tk does its drawing in idle callbacks, so the
    widgets have to have drawn themselves while painting was still held back.

    `repaint` narrows what is repainted when the freeze lifts: those widgets
    (and their children) instead of everything under `widget`. For a caller
    that knows exactly what changed -- a page swap changes the header and the
    page raised, and nothing else under the content area.
    """

    def __init__(self, widget, repaint=None):
        self._widget = widget
        self._repaint = tuple(repaint) if repaint else ()
        self._hwnd: Optional[int] = None

    def __enter__(self):
        api = _USER32
        if api is None:
            return self
        try:
            # An unmapped window cannot be seen anyway, and WM_SETREDRAW(TRUE)
            # sets WS_VISIBLE — un-freezing one would show a window Tk hid.
            if not self._widget.winfo_ismapped():
                return self
            hwnd = int(self._widget.winfo_id())
        except Exception:
            return self
        depth = _freeze_depth.get(hwnd, 0)
        if depth == 0:
            try:
                api.SendMessageW(hwnd, _WM_SETREDRAW, 0, 0)
            except Exception:
                return self
        _freeze_depth[hwnd] = depth + 1
        self._hwnd = hwnd
        return self

    def __exit__(self, *_exc):
        hwnd = self._hwnd
        if hwnd is None:
            return False
        self._hwnd = None
        depth = _freeze_depth.get(hwnd, 1) - 1
        if depth > 0:
            _freeze_depth[hwnd] = depth
            return False
        _freeze_depth.pop(hwnd, None)
        api = _USER32
        try:
            api.SendMessageW(hwnd, _WM_SETREDRAW, 1, 0)
        except Exception:
            pass
        targets = []
        for w in self._repaint:
            try:
                targets.append(int(w.winfo_id()))
            except Exception:
                targets = []            # anything odd: repaint it all
                break
        for h in (targets or [hwnd]):
            try:
                api.RedrawWindow(h, None, None, _REDRAW_FLAGS)
            except Exception:
                pass
        return False     # never swallow the body's exception


# ---------------------------------------------------------------------------
# Custom Widgets
# ---------------------------------------------------------------------------

class RoundedFrame(ctk.CTkFrame):
    """Premium rounded card backed by CustomTkinter (real anti-aliased corners
    + hairline border). Exposes ``.inner`` — a plain tk.Frame inset just inside
    the rounding — so every existing pack/grid call-site keeps working as-is.
    Children set ``bg=bg_color`` explicitly, matching the card surface.
    """

    def __init__(self, parent, bg_color=BG_CARD, border_color=BORDER,
                 radius=RAD_MD, border_width=1, height=None, **kw):
        kw.pop("width", None)
        parent_bg = _widget_bg(parent)
        super().__init__(
            parent, fg_color=bg_color, border_color=border_color,
            corner_radius=radius, border_width=border_width,
            bg_color=parent_bg if parent_bg else "transparent",
        )
        self._bg_color = bg_color
        # Inset the inner frame so its square corners fall inside the radius.
        inset = border_width + 3
        self._inner = tk.Frame(self, bg=bg_color)
        self._inner.pack(fill="both", expand=True, padx=inset, pady=inset)

    @property
    def inner(self) -> tk.Frame:
        return self._inner


class PillButton(ctk.CTkButton):
    """Pill-shaped button backed by CustomTkinter (smooth hover, real rounded
    corners). Drop-in for the old Canvas button: the ``bg_color`` arg is the
    button *fill* and ``fg_color`` is the *text* color (legacy naming).
    """

    def __init__(self, parent, text="", command=None, bg_color=ACCENT,
                 hover_color=ACCENT_HOVER, fg_color=TEXT_PRIMARY,
                 width=120, height=36, font_size=10, press_color=None):
        parent_bg = _widget_bg(parent)
        super().__init__(
            parent, text=text, command=command,
            width=width, height=height, corner_radius=height // 2,
            fg_color=bg_color, hover_color=hover_color, text_color=fg_color,
            bg_color=parent_bg if parent_bg else "transparent",
            border_width=0, border_spacing=0,
            font=ctk.CTkFont(family=FONT_FAMILY, size=font_size + 1, weight="bold"),
        )

    def configure_text(self, text: str) -> None:
        self.configure(text=text)


class StatusDot(tk.Canvas):
    """Tiny glowing status indicator."""

    def __init__(self, parent, color=TEXT_MUTED, size=10):
        try:
            bg = parent.cget("bg")
        except Exception:
            bg = BG_CARD
        super().__init__(parent, width=size + 6, height=size + 6,
                         highlightthickness=0, bg=bg)
        self._size = size
        self._pad = 3
        self.set_color(color)

    def set_color(self, color: str) -> None:
        self.color = color          # read back when a card is rebuilt
        self.delete("all")
        s, p = self._size, self._pad
        # glow
        self.create_oval(p - 2, p - 2, p + s + 2, p + s + 2,
                         fill="", outline=color, width=1)
        # solid dot
        self.create_oval(p, p, p + s, p + s, fill=color, outline="")


# Access code that reveals the Alert Feed settings. The feed ships
# pre-configured so a downloaded copy just works, and the settings panel stays
# hidden behind this code — both so a stray edit cannot break the feed and so
# nothing about where the alerts come from is on screen for a customer.
#
# It is a curtain, not a secret. The values it hides sit in .env in plain text
# next to this file, so the default below must never be a real credential —
# this file is committed to a public repository, and anything literal here is
# published to everyone who clones it. A broker password was once used as this
# code; that published the password. Override with RSAMAXXED_CONFIG_UNLOCK in
# .env to change it, and pick a string you do not use to log in anywhere.
FEED_CONFIG_UNLOCK = os.environ.get(
    "RSAMAXXED_CONFIG_UNLOCK", "").strip() or "1591"

# Shown on the lock bar whenever the settings are hidden. It says the feed is
# working rather than that something is missing, because for everyone except
# the operator there is genuinely nothing to do here.
FEED_LOCKED_HINT = "Feed settings are hidden — plays load automatically"

SELLS_FILE = ROOT_DIR / "sells.json"

# How many days of exits the dashboard SELL card shows. Exits stay useful only
# while you might still be holding the position.
SELL_MAX_AGE_DAYS = 10
# ...unless the journal still shows the position open at a brokerage the exit
# named: then it stays (see _merge_sells) up to this hard ceiling, so an exit
# is never forgotten while we are still in the trade it was about.
SELL_OPEN_MAX_AGE_DAYS = 45
# Rows the Command Center card shows before deferring to the Exits tab.
# Dated headers cost vertical space, so this is a card, not a ledger.
SELL_ALERTS_SHOWN = 12


def _load_sells() -> List[Dict[str, Any]]:
    """Recorded SELL alerts, newest first. [] if the file is missing/unreadable.

    UNREADABLE IS NOT EMPTY. This read 'utf-8' (a BOM made a good file
    unreadable) and returned [] on any error, and the next feed pull saved
    _merge_sells([], incoming) straight over it: every exit the feed no longer
    serves -- older ones, ones imported from the alert channel -- was gone, and
    the shares they called were never sold. atomic.load_state keeps the file,
    copies it aside, says so, and blocks _save_sells until it reads again.
    """
    data = atomic.load_state(SELLS_FILE, [])
    if not isinstance(data, list):
        # Parses, but isn't the list this file holds (hand-edited, or another
        # tool wrote it): as unreadable as a corrupt one. Block the save so the
        # next pull can't write _merge_sells([], incoming) over it.
        why = f"{Path(SELLS_FILE).name} is not a list of exits — left untouched"
        with atomic._UNREADABLE_LOCK:
            first = atomic._key_of(SELLS_FILE) not in atomic._UNREADABLE
            atomic._UNREADABLE[atomic._key_of(SELLS_FILE)] = why
        if first and callable(atomic.on_unreadable):
            try:
                atomic.on_unreadable(SELLS_FILE, why)
            except Exception:
                pass
        return []
    rows = [s for s in data if isinstance(s, dict)]
    rows.sort(key=lambda s: (str(s.get("sell_date") or ""),
                             str(s.get("posted_at") or "")), reverse=True)
    return rows


def _save_sells(sells: List[Dict[str, Any]]) -> bool:
    """True once written. False -- nothing written -- on any OSError, incl.
    StateUnreadable: never over a file we could not read (see _load_sells)."""
    try:
        _write_json(SELLS_FILE, sells)
    except OSError:
        return False
    return True


def _store_exits(incoming: List[Dict[str, Any]]) -> bool:
    """Merge `incoming` into sells.json. True once it is on disk.

    A read that hit a transient lock (Drive, antivirus) blocks the save that
    follows it (atomic.load_state): the exit was dropped while last_sell_id
    had already moved past it, so no later pull fetched it again. One more
    read-merge-save first -- a good read lifts the block, and the merge is
    then against the real file, never over it.
    """
    for _ in range(2):
        if _save_sells(_merge_sells(_load_sells(), incoming)):
            return True
    return False


#: Exits a pull could not save (sells.json unreadable/locked), held for the
#: next pull rather than lost. Feed workers run on threads: guarded.
_PENDING_EXITS_LOCK = threading.Lock()


def _keep_exits(app, incoming: List[Dict[str, Any]]) -> Optional[bool]:
    """Store `incoming` plus anything an earlier pull could not save.

    None: nothing to store. True: on disk. False: still not saved -- every
    row is kept on `app._pending_exits` for the next pull and the user is
    told loudly, because an exit nobody stores is shares nobody sells."""
    with _PENDING_EXITS_LOCK:
        pending = list(getattr(app, "_pending_exits", None) or [])
        rows = pending + [r for r in (incoming or []) if isinstance(r, dict)]
        if not rows:
            return None
        if _store_exits(rows):
            app._pending_exits = []
            return True
        by_id: Dict[str, Dict[str, Any]] = {}
        for r in rows:
            sid = str(r.get("source_id") or "")
            by_id[sid or f"{r.get('symbol')}:{r.get('sell_date')}"] = r
        app._pending_exits = list(by_id.values())
        n = len(app._pending_exits)
    syms = ", ".join(sorted({str(r.get("symbol") or "?") for r in app._pending_exits}))
    msg = (f"{_plural(n, 'exit')} ({syms}) could not be saved — "
           f"{SELLS_FILE.name} is locked or unreadable. Kept in memory and "
           f"retried on the next pull; do not close the app until it saves.")
    try:
        app.after(0, lambda: app._push_notification(msg, "error"))
        log = getattr(app, "_log", None)
        if callable(log):
            app.after(0, lambda: log(f"Exits: {msg}", "error"))
    except Exception:
        pass
    return False


def _merge_sells(existing: List[Dict[str, Any]],
                 incoming: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Union on source_id, newest first, aged out past SELL_MAX_AGE_DAYS.

    Feed pulls overlap (the same message can arrive twice after a re-import),
    so dedup on the feed's own message id rather than symbol — the same ticker
    legitimately exits more than once.

    An exit past SELL_MAX_AGE_DAYS is KEPT while the journal still shows shares
    open at a brokerage it named, up to SELL_OPEN_MAX_AGE_DAYS. sells.json is
    the only record that an exit was called at all, so ageing one out under a
    position we still hold took the leg off Sell now and out of auto-sell's
    reach — the shares sat there with nothing left to say "sell these".
    """
    from datetime import timedelta
    now = datetime.now()
    cutoff = (now - timedelta(days=SELL_MAX_AGE_DAYS)).strftime("%Y-%m-%d")
    hard = (now - timedelta(days=SELL_OPEN_MAX_AGE_DAYS)).strftime("%Y-%m-%d")
    by_id: Dict[str, Dict[str, Any]] = {}
    for s in list(existing) + list(incoming):
        if not isinstance(s, dict):
            continue
        sid = str(s.get("source_id") or "")
        key = sid or f"{s.get('symbol')}:{s.get('sell_date')}"
        by_id[key] = s

    ledger: Optional[Dict[tuple, List[float]]] = None    # read only if needed
    renames: Dict[str, str] = {}

    def keep(s: Dict[str, Any]) -> bool:
        nonlocal ledger, renames
        when = str(s.get("sell_date") or "")
        if not when or when >= cutoff:
            return True
        if when < hard:
            return False
        if ledger is None:
            ledger = _sell_share_ledger()
            renames = _known_renames()
        sym = str(s.get("symbol") or "").upper()
        # Both names of a renamed play: the buy is journaled as AGAE, the
        # exit says AIFA.
        names = {sym, renames.get(sym, sym)}
        names |= {new for new, old in renames.items() if old in names}
        for b in _sell_leg_broker_keys(s):
            bought = sum(ledger.get((b, n), [0.0, 0.0])[0] for n in names)
            sold = sum(ledger.get((b, n), [0.0, 0.0])[1] for n in names)
            if bought - sold > 1e-9:
                return True
        return False

    rows = [s for s in by_id.values() if keep(s)]
    rows.sort(key=lambda s: (str(s.get("sell_date") or ""),
                             str(s.get("posted_at") or "")), reverse=True)
    return rows


def _parse_iso_utc(value: Any) -> Optional[datetime]:
    """Parse an ISO timestamp to an aware UTC datetime, or None.

    Naive values are read as UTC: everything that writes one here
    (lifecycle._now) is UTC already, and guessing local for a stray naive
    string would shift a comparison by hours in the direction of selling MORE.
    """
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def _sell_leg_broker_keys(sell: Dict[str, Any]) -> List[str]:
    """App broker keys a sell alert names, in the order it wrote them.

    'Wells Fargo x3' -> 'wellsfargo'. Only brokers this tool actually trades
    survive: the feed names brokerages we don't automate (Webull, Vanguard) and
    there is no chip on the desk to arm for those.
    """
    keys: List[str] = []
    for leg in sell.get("legs") or []:
        if not isinstance(leg, dict):
            continue
        key = lifecycle.app_key(str(leg.get("broker") or ""))
        if key in BROKER_MODULES and key not in keys:
            keys.append(key)
    return keys


def _qty_text(qty: float) -> str:
    """Shares, without a trailing ".0" on the whole numbers that are the norm.

    RSA positions are whole shares almost everywhere, but a reverse split
    leaves real fractions behind, so this can't just be an int().
    """
    try:
        q = float(qty)
    except (TypeError, ValueError):
        return "0"
    if abs(q - round(q)) < 1e-9:
        return str(int(round(q)))
    return f"{q:.4f}".rstrip("0").rstrip(".")


#: What one brokerage's share of a play is doing.
SELL_NOW = "sell_now"     # we hold it there AND an exit has been called there
SELL_WAIT = "waiting"     # we hold it there, no exit called there yet
SELL_DONE = "done"        # we are out of it there
SELL_NONE = "no_position"  # an exit was called there, but we never got in


@dataclass(frozen=True)
class SellLeg:
    """One brokerage's share of one play."""

    broker: str
    bought: float
    sold: float
    left: float
    state: str
    alert_date: str = ""
    failed_accounts: int = 0
    fail_reason: str = ""

    @property
    def label(self) -> str:
        return rsa_feed.normalize_broker(self.broker)


@dataclass(frozen=True)
class SellPlay:
    """One ticker, and where it stands at every brokerage that ever held it.

    The card used to be a list of ALERTS, but an exit is called per brokerage
    and they arrive days apart, so one ticker became four rows scattered across
    three tabs — BYAH was simultaneously under Sell Alerts, Partial and Sold.
    Nothing on screen answered the only question actually being asked, which is
    "where do I stand on this play". A play is the unit; a brokerage is a row
    inside it.
    """

    symbol: str
    exit_price: Optional[float]
    legs: tuple
    last_alert: str = ""

    @property
    def bought(self) -> float:
        return sum(l.bought for l in self.legs)

    @property
    def left(self) -> float:
        return sum(l.left for l in self.legs)

    @property
    def sold(self) -> float:
        return sum(l.sold for l in self.legs)

    def of(self, state: str) -> tuple:
        return tuple(l for l in self.legs if l.state == state)

    @property
    def bucket(self) -> str:
        """Which tab. Actionable beats everything: a play with one broker ready
        to sell belongs under Sell now even if four others are still waiting."""
        if self.of(SELL_NOW):
            return "now"
        return "holding" if self.left > 1e-9 else "closed"

    @property
    def ready_value(self) -> float:
        """Roughly what the sellable legs are worth, for ordering the worklist."""
        if not self.exit_price:
            return 0.0
        return sum(l.left for l in self.of(SELL_NOW)) * float(self.exit_price)


def _known_renames(extra: Optional[Dict[str, str]] = None,
                   names: Any = ()) -> Dict[str, str]:
    """CURRENT ticker -> bought-under ticker, for folding the sell-side journal.

    The stored board's renames (lifecycle.saved_renames), overlaid with
    `extra` (the in-memory board, when the caller has it), plus `names` -- the
    tickers a caller already says are ONE play (AIFA, AGAE) -- all filed under
    one name. Best effort: an unreadable board just folds less.
    """
    m: Dict[str, str] = {}
    try:
        m.update({str(k).upper(): str(v).upper()
                  for k, v in lifecycle.saved_renames().items() if k and v})
    except Exception:
        pass
    m.update({str(k).upper(): str(v).upper()
              for k, v in (extra or {}).items() if k and v})
    group = [str(n).upper() for n in names if n]
    if len(set(group)) > 1:
        anchor = next((m[n] for n in group if n in m), group[-1])
        for k, v in list(m.items()):
            if v in group:
                m[k] = anchor
        for n in group:
            if n != anchor:
                m[n] = anchor
    return {k: v for k, v in m.items() if k != v}


def _sell_side_rows(renames: Optional[Dict[str, str]] = None,
                    names: Any = ()) -> List[Dict[str, Any]]:
    """The journal as the sell side nets it: renames folded, THEN split-adjusted.

    The order matters. split_adjusted restates a fractional sell against the
    holding under the same ticker, and a renamed play keeps its buy under the
    old name (AGAE) and its remnant sale under the new one (AIFA 0.05). Not
    folded first, the remnant met no holding, stayed 0.05, and left 0.95 of a
    phantom open share that auto-sell queued for sale. Each folded row keeps
    the ticker it was journaled under as `executed_symbol`.
    """
    return trade_journal.split_adjusted(trade_journal.fold_renames(
        trade_journal.get_trades(), _known_renames(renames, names)))


def _journaled_symbol(t: Dict[str, Any]) -> str:
    """The ticker a (possibly folded) journal row was recorded under."""
    return str(t.get("executed_symbol") or t.get("symbol") or "").upper()


def _sell_share_ledger(renames: Optional[Dict[str, str]] = None) -> Dict[tuple, List[float]]:
    """(broker, SYMBOL) -> [bought, sold] in SHARES.

    Shares, not accounts. Counting accounts is what made LBGJ at Robinhood read
    "3/3 sold" while three shares were still open there — six were bought across
    three accounts and three were sold, so the account sets matched exactly and
    the arithmetic looked complete. Split-adjusted for the same reason every
    other position figure is -- after folding renames, see _sell_side_rows.
    Keyed by the ticker each row was journaled under.
    """
    out: Dict[tuple, List[float]] = {}
    try:
        rows = _sell_side_rows(renames)
    except Exception:
        return out
    for t in rows:
        # Under the ticker it was JOURNALED as: callers sum both names of a
        # renamed play themselves, and look a single name up directly.
        sym = _journaled_symbol(t)
        if not sym:
            continue
        try:
            qty = float(t.get("qty") or 0.0)
        except (TypeError, ValueError):
            continue
        rec = out.setdefault((str(t.get("broker") or ""), sym), [0.0, 0.0])
        rec[0 if t.get("side") == "buy" else 1] += qty
    return out


def _acct_net_key(broker: Any, account_id: Any) -> str:
    """The identity sell ledgers NET on: one account however its label drifted.

    A buy journaled as 'Fidelity 1 · Individual (Z1)' and its sell as
    'Fidelity 1 · FinTec (Z1)' — or 'Robinhood 1 | …' then the bare login-1
    form — are one account. Netted on the raw label they leave a phantom open
    account that the exits board offers for sale again. Keys compare within
    one broker only.
    """
    return trade_journal.account_key(
        trade_journal.canonical_account(broker, account_id))


def _leg_open_accounts(broker: str, symbol: str) -> List[tuple]:
    """(account_id, shares) still open at one brokerage, oldest account first.

    Per ACCOUNT, because that is the granularity the journal records and the
    only granularity a resolution can be written at: "LBGJ is done at
    Robinhood" is three separate accounts that each have to stop counting.

    `symbol` may also be several tickers — the current one and the one we
    bought it under (AIFA, AGAE) — netted together per account, so a buy under
    the old name and a sell under the new one close each other out.

    Netted per account NUMBER (_acct_net_key), reported under the NEWEST
    label: that is what goes out as only_accounts, and the brokers match it
    against what they show today.
    """
    if isinstance(symbol, (tuple, list, set, frozenset)):
        symbols = {str(s or "").upper() for s in symbol if s}
    else:
        symbols = {str(symbol or "").upper()}
    net: Dict[str, float] = {}
    label: Dict[str, str] = {}
    try:
        # Renames folded before the split lens (see _sell_side_rows), so a
        # remnant sold under the new name restates against the buy under the
        # old one; rows are still picked by the ticker they were journaled as.
        rows = _sell_side_rows(names=sorted(symbols))
    except Exception:
        return []
    for t in rows:
        if (_journaled_symbol(t) not in symbols
                or str(t.get("broker") or "") != broker):
            continue
        try:
            qty = float(t.get("qty") or 0.0)
        except (TypeError, ValueError):
            continue
        acct = str(t.get("account_id") or "")
        k = _acct_net_key(broker, acct)
        if acct or k not in label:
            label[k] = acct     # file order is chronological: the last one wins
        net[k] = net.get(k, 0.0) + (qty if t.get("side") == "buy" else -qty)
    return sorted((label[k], q) for k, q in net.items() if q > 1e-9)


def _public_raw_positions(symbols, rows=None) -> Dict[str, List[float]]:
    """Public account label -> [gross bought, raw sold] across `symbols`.

    RAW journal rows, deliberately NOT split_adjusted. That lens restates a
    fractional sell as closing the whole pre-split share, which is right for
    P/L and wrong for one thing Public does: it can credit 0.2 of a share after
    a split, and weeks later round the account up to 0.98. Sell the 0.2 and the
    adjusted journal calls the account closed while 0.98 is sitting in it. The
    raw figures still say what happened: bought 1, sold 0.2. Closes count as
    sold -- a position the user marked gone is not ours to sell again.

    Summed across the alert and current ticker, because the buy is journaled
    under the name we bought it as and a later sell may be under the new one.
    """
    return _raw_positions("public", symbols, rows)


def _raw_positions(broker: str, symbols, rows=None) -> Dict[str, List[float]]:
    """_public_raw_positions for any brokerage: account -> [bought, sold], raw.

    Netted per account (_acct_net_key) so a relabelled account is one entry,
    keyed by its NEWEST label — Public matches its caps on today's label."""
    syms = {str(s or "").upper() for s in symbols if s}
    out: Dict[str, List[float]] = {}
    by_key: Dict[str, List[float]] = {}
    label: Dict[str, str] = {}
    if rows is None:
        try:
            rows = trade_journal.get_trades()
        except Exception:
            return out
    for t in rows:
        if (str(t.get("broker") or "") != broker
                or str(t.get("symbol") or "").upper() not in syms):
            continue
        try:
            qty = float(t.get("qty") or 0.0)
        except (TypeError, ValueError):
            continue
        acct = str(t.get("account_id") or "").strip()
        k = _acct_net_key(broker, acct)
        if acct or k not in label:
            label[k] = acct
        rec = by_key.setdefault(k, [0.0, 0.0])
        rec[0 if t.get("side") == "buy" else 1] += qty
    for k, rec in by_key.items():
        prev = out.get(label[k])
        if prev is None:
            out[label[k]] = rec
        else:                   # two keys, one label: never drop either's shares
            prev[0] += rec[0]
            prev[1] += rec[1]
    return out


def _public_sell_caps(symbols, rows=None) -> Dict[str, float]:
    """Per Public account, the most a holdings-sized sell may take: what this
    tool BOUGHT there, gross, for accounts it is not yet out of.

    THE RULE (owner-approved, 2026-09-25). An account is eligible when we ever
    bought the play there AND the raw net (bought - sold) is still above zero.
    Its cap is the gross buy, and public.execute_trade sells min(held, cap):

        bought 1, nothing sold, split left 0.0333       -> sells 0.0333
        bought 1, split rounded up to 1                  -> sells 1
        bought 1, sold 0.2, Public later rounded to 0.98 -> sells 0.98
        bought 1, account also held 100 of its own       -> sells 1, never 101
        bought 1, sold 1 (or 0.2 then 0.98)              -> not eligible

    The gross buy is the cap rather than what is left of it because the units
    do not line up: 0.98 of a post-split share after selling 0.2 is not
    "0.8 remaining" of anything. The one thing that is always true is that we
    never sell more shares than we put in.
    """
    return {acct: bought
            for acct, (bought, sold) in _public_raw_positions(symbols, rows).items()
            if acct and bought > 1e-9 and bought - sold > 1e-9}


def _broker_sell_cap(broker: str, symbols, rows=None) -> Tuple[Optional[float], int]:
    """(most one order may sell per account, accounts the journal holds) at a
    brokerage whose module sends ONE quantity to every account.

    Public sizes each account itself (_public_sell_caps). Everywhere else the
    exit leg is lifecycle.resolve's smallest live balance, sent to every
    account, and a live balance includes any shares the customer held on his
    own: a broker with one account holding 100 of his and 1 of ours read as
    "sell 101".

    The same rule as Public, applied per brokerage: never sell more shares in
    an account than this tool put in. The figure is the GROSS raw buy, in the
    units we bought in, for the same reason given there — a reverse split only
    ever shrinks a share count (a round-up brings 1 back to at most 1), so the
    pre-split buy is always at least what is ours afterwards, and no
    split-adjusted figure has to be trusted to line up. One quantity reaches
    every account, so the cap is the SMALLEST such buy among the accounts we
    are still in.

    (None, 0) when the journal shows no open account here: nothing to cap
    against, and the caller leaves the size alone and says so.
    """
    caps = [bought for acct, (bought, sold) in _raw_positions(broker, symbols, rows).items()
            if bought > 1e-9 and bought - sold > 1e-9]
    if not caps:
        return None, 0
    return min(caps), len(caps)


def _capped_leg_qty(leg, cap: Optional[float]) -> Tuple[str, bool]:
    """(quantity to send, whether the cap cut it) for one non-Public exit leg."""
    if cap is None:
        return leg.qty, False
    try:
        live = Decimal(str(leg.qty))
        lim = Decimal(_cap_text(cap))
    except (InvalidOperation, ValueError, TypeError):
        return leg.qty, False
    if lim <= 0 or live <= lim:
        return leg.qty, False
    return lifecycle.qty_text(lim), True


def _exit_leg_plan(resolved, autosell: bool = False) -> Dict[str, Any]:
    """Which legs of a resolved exit may actually be sent, sized and aimed.

    Worked out AT FIRE TIME from the journal, not from whatever the board or
    the confirm dialog saw: a leg sold by hand, or by an earlier batch, while
    this one waited in the queue or on the dialog has no open account left and
    is dropped rather than sold a second time.

    Per non-Public leg:

      * no open account in the journal          -> dropped (logged)
      * auto-sell with nothing to cap against    -> refused, handed back
      * a broker that can target accounts        -> only_accounts = ours
      * one that cannot, holding the name in MORE
        accounts than we bought in               -> auto-sell hands it to a
                                                    human; by hand it warns
                                                    before the click

    Public is passed through untouched: it sizes and caps every account itself
    from a live read (_public_sell_caps), and a late round-up is closed in the
    adjusted journal while still being ours in the raw one.

    Returns legs, qty (key -> str), only (key -> account ids), notes (cap
    remarks for the log), dropped, refused (hand-back reasons), human (legs
    left for a person) and warn (what the confirm dialog must say first).
    """
    task = resolved.task
    syms = tuple(dict.fromkeys(s for s in (task.symbol, task.alert_symbol) if s))
    plan: Dict[str, Any] = {"legs": [], "qty": {}, "only": {}, "notes": [],
                            "dropped": [], "refused": [], "human": [], "warn": []}
    for leg in resolved.legs:
        if leg.key == "public":
            plan["legs"].append(leg)
            plan["qty"][leg.key] = leg.qty
            continue
        open_accts = _leg_open_accounts(leg.key, syms)
        if not open_accts:
            plan["dropped"].append(f"{leg.broker}: the journal shows no open "
                                   f"{task.symbol} account there any more — "
                                   f"not selling it again")
            continue
        cap, _n = _broker_sell_cap(leg.key, syms)
        if cap is None and autosell:
            # Nothing on record to cap against means the live balance would go
            # out as-is, and nobody is watching to notice "sell 101".
            plan["refused"].append(f"{leg.broker}: no buy on record to cap the "
                                   f"sell at")
            continue
        qty, cut = _capped_leg_qty(leg, cap)
        if cut and autosell:
            # Nobody is watching an auto-sell to notice "sell 101". By hand
            # the confirm dialog showed the live size, and that is the
            # user's call to make.
            plan["notes"].append(f"{leg.broker}: live balance {leg.qty} is more "
                                 f"than this tool bought there — selling {qty}")
        elif cut:
            plan["notes"].append(f"{leg.broker}: selling {leg.qty}, more than the "
                                 f"{qty} this tool bought there — the rest may "
                                 f"be your own shares")
            qty = leg.qty
        ours = len(open_accts)
        ids = [a for a, _q in open_accts if a]
        if leg.key in RETRYABLE_ACCOUNT_BROKERS and len(ids) == ours:
            # Aimed at the accounts this tool bought in, and only those. An
            # account holding only the customer's own shares is never touched.
            plan["only"][leg.key] = ids
        elif leg.accounts > ours:
            # The module cannot be pointed at a subset of accounts, so every
            # account holding the name would be sold — including ones holding
            # only the customer's own shares.
            msg = (f"{leg.broker}: {leg.accounts} accounts hold {task.symbol} but "
                   f"this tool bought in {ours} — selling there would sell the "
                   f"others too")
            if autosell:
                plan["human"].append(msg)
                continue
            plan["warn"].append(msg)
        plan["legs"].append(leg)
        plan["qty"][leg.key] = qty
    return plan


def _app_live_brokers_in_flight(app) -> set:
    """Brokers with an order out, minus mirror's written-off (wedged) ones.

    A wedged broker stays in _brokers_in_flight so nothing more is sent
    THERE until its batch reports; it is left out here so it cannot make
    the whole app read as mid-trade."""
    wedged = getattr(app, "_mirror_wedged", None)
    wedged = set(wedged) if isinstance(wedged, (dict, set, list, tuple)) else set()
    return set(getattr(app, "_brokers_in_flight", None) or ()) - wedged


def _app_recompute_trade_in_flight(app) -> None:
    app._trade_in_flight = bool(_app_live_brokers_in_flight(app))


def _mirror_owed_list(app) -> List[dict]:
    owed = getattr(app, "_mirror_owed", None)
    if owed is None:
        owed = app._mirror_owed = []
    return owed


def _mirror_owe(app, broker: str, pick: Dict[str, str],
                attempts: int = 0, after: str = "",
                accounts: Optional[List[str]] = None) -> None:
    """Remember that `broker` still owes `pick`: it was wedged at launch, or
    its leg failed with nothing sent while another broker filled.

    `attempts` counts the launches that already failed there; `after` (an ISO
    timestamp) holds the record back until then, so a login that just failed
    is not hammered again twenty seconds later."""
    owed = _mirror_owed_list(app)
    rec = {"broker": str(broker), "symbol": str(pick.get("symbol") or "").upper(),
           "date": str(pick.get("date") or ""), "note": str(pick.get("note") or "")}
    if pick.get("last_buy"):
        # The alert's last day to buy: the retry's age gate needs it, or a
        # retry buys after the last day (or drops a debt the last day keeps).
        rec["last_buy"] = str(pick.get("last_buy"))[:10]
    if attempts:
        rec["attempts"] = str(int(attempts))
    if after:
        rec["after"] = str(after)
    if accounts:
        # Only these accounts at that broker (RETRYABLE_ACCOUNT_BROKERS): the
        # rest of its accounts filled, and a whole-broker re-send buys them
        # a second time.
        rec["accounts"] = sorted({str(a) for a in accounts if a})
    for o in owed:
        if (o.get("broker") == rec["broker"] and o.get("symbol") == rec["symbol"]
                and o.get("date") == rec["date"]):
            if rec.get("last_buy") and not o.get("last_buy"):
                o["last_buy"] = rec["last_buy"]
            if o.get("accounts") and rec.get("accounts"):
                o["accounts"] = sorted(set(o["accounts"]) | set(rec["accounts"]))
            elif not rec.get("accounts"):
                o.pop("accounts", None)      # the whole broker is owed
            return
    owed.append(rec)


def _mirror_owed_from(saved: Dict[str, Any]) -> List[dict]:
    """The owed records in a loaded mirror_state.json. `accounts` survives
    as a list: dropping it on a restart would widen an account-targeted retry
    to the whole broker -- a second buy at every account that filled."""
    out: List[dict] = []
    for o in (saved or {}).get("owed") or []:
        if not (isinstance(o, dict) and o.get("broker") and o.get("symbol")):
            continue
        rec = {k: str(o.get(k) or "") for k in ("broker", "symbol", "date", "note",
                                                "attempts", "after")}
        if o.get("last_buy"):       # absent on records saved before it was kept
            rec["last_buy"] = str(o.get("last_buy"))[:10]
        accts = o.get("accounts")
        if isinstance(accts, (list, tuple)) and accts:
            rec["accounts"] = [str(a) for a in accts if a]
        elif accts:
            continue        # unreadable account list: never guess "all of them"
        out.append(rec)
    return out


#: How long a broker whose leg failed with nothing sent waits before mirror
#: sends it that pick again: about the next scheduled check, not the next
#: drain tick twenty seconds on.
MIRROR_LEG_RETRY_MS = 1_800_000  # 30 min

#: How a failed-list note for a pick waiting on a stuck broker begins.
MIRROR_HELD_FOR_NOTE = "held for"


def _mirror_retry_at_text() -> str:
    """When a just-owed leg becomes due again (MIRROR_LEG_RETRY_MS), as HH:MM."""
    return (datetime.now() + timedelta(milliseconds=MIRROR_LEG_RETRY_MS)).strftime("%H:%M")


#: Nothing-sent failures a retry cannot fix -- the broker refused the order or
#: the account can't take it. Chase refuses ~37% of pending-split names
#: outright; re-sending those three times only adds noise.
_MIRROR_PERMANENT_FAILURE = (
    "rejected", "insufficient", "invalid", "not enough shares", "no tradable",
    "no accounts", "cannot trade specific accounts", "missing ",
)


def _mirror_leg_retryable(result: Dict[str, Any]) -> bool:
    """A broker leg that filled NO account, every failure positively says
    nothing was sent, no account may hold a live order, and nothing says the
    broker refused it for good. Only such a leg is safe and useful to send
    again on its own."""
    try:
        if int(result.get("ok_accounts") or 0) > 0:
            return False
    except (TypeError, ValueError):
        return False
    if not _result_nothing_sent(result):
        return False
    if any(_account_order_may_exist(a) for a in (result.get("accounts") or [])):
        return False
    texts = " | ".join(_failed_texts(result)).lower()
    return not any(w in texts for w in _MIRROR_PERMANENT_FAILURE)


def _mirror_int(value: Any) -> int:
    try:
        return max(0, int(str(value or "0")))
    except (TypeError, ValueError):
        return 0


def _mirror_owed_done(app, broker: str, pick: Dict[str, str]) -> None:
    sym = str(pick.get("symbol") or "").upper()
    d = str(pick.get("date") or "")
    owed = _mirror_owed_list(app)
    owed[:] = [o for o in owed if not (o.get("broker") == broker
                                       and o.get("symbol") == sym
                                       and o.get("date") == d)]


def _mirror_launched_from(saved: Dict[str, Any]) -> Dict[tuple, dict]:
    """The launch markers in a loaded mirror_state.json: (date, SYMBOL) ->
    {"at": ISO time the orders started, "brokers": [...]}."""
    out: Dict[tuple, dict] = {}
    for x in (saved or {}).get("launched") or []:
        if not isinstance(x, (list, tuple)) or len(x) < 2:
            continue
        info = {"at": str(x[2]) if len(x) > 2 else "",
                "brokers": [str(b) for b in x[3]] if len(x) > 3
                and isinstance(x[3], (list, tuple)) else []}
        out[(str(x[0]), str(x[1]).upper())] = info
    return out


def _mirror_lost_runs(launched: Dict[tuple, dict], runs: list) -> list:
    """Launches with no run in mirror_runs.json, as interrupted-run stand-ins.

    mirror_runs.json is written by a background thread that retries a locked
    file and loses the queued write on a kill; the launch marker was saved
    before any order went out. Without this a pick killed mid-run under that
    lock vanished: no run, so nothing on NEEDS ATTENTION."""
    have = {(str(r.get("pick_date") or ""), str(r.get("symbol") or "").upper())
            for r in runs or [] if (r.get("side") or "buy") == "buy"}
    out = []
    for (d, sym), info in (launched or {}).items():
        if (d, sym) in have or not info.get("at") or not info.get("brokers"):
            continue
        out.append({"id": f"launch:{d}:{sym}", "symbol": sym, "pick_date": d,
                    "side": "buy", "started_at": info["at"], "finished_at": "",
                    "brokers": list(info["brokers"]), "legs": [],
                    "dry_run": False, "_lost": True})
    return out


def _mirror_cancel_owed(app, key: tuple) -> int:
    """Drop every owed record for one pick, (date, SYMBOL); returns how many.

    The way out of an automatic retry: the user bought it there by hand
    (Mark done, "Stop retrying" on the Mirror page) or a later alert held
    the play. A retry the user can't cancel is a second share."""
    try:
        d, sym = str(key[0]), str(key[1]).upper()
    except (IndexError, TypeError):
        return 0
    owed = _mirror_owed_list(app)
    before = len(owed)
    owed[:] = [o for o in owed if not (o.get("symbol") == sym and o.get("date") == d)]
    return before - len(owed)


def _mirror_owed_for(app, key: tuple) -> List[dict]:
    """The owed records still open for one pick, (date, SYMBOL)."""
    try:
        d, sym = str(key[0]), str(key[1]).upper()
    except (IndexError, TypeError):
        return []
    return [o for o in _mirror_owed_list(app)
            if o.get("symbol") == sym and o.get("date") == d]


_LOGIN_N_REFUSED = re.compile(r"\blogin(?: \d+)? (?:failed|refused|rejected)\b", re.I)


def _mirror_account_unsent(acct: Dict[str, Any]) -> bool:
    """One failed account that positively sent nothing and that a retry can
    fix: no may-exist wording, a nothing-sent phrase (or "login 2 failed"),
    and not a refusal for good."""
    if not isinstance(acct, dict) or acct.get("ok") or _account_order_may_exist(acct):
        return False
    msg = str(acct.get("message") or "")
    low = msg.lower()
    if any(w in low for w in _MAY_HAVE_GONE_OUT):
        return False
    login = "login failed" in low or bool(_LOGIN_N_REFUSED.search(msg))
    # "login 2 rejected the password" is a login that didn't get in, not the
    # broker refusing the order: a retry can fix it.
    if not login and any(w in low for w in _MIRROR_PERMANENT_FAILURE):
        return False
    return login or _nothing_was_sent(msg)


def _mirror_unsent_accounts(result: Dict[str, Any]) -> List[str]:
    """Account ids in one broker result that failed with nothing sent."""
    return [str(a.get("account_id")) for a in (result.get("accounts") or [])
            if _mirror_account_unsent(a) and a.get("account_id")]


def _mirror_maybe_live_brokers(results) -> List[str]:
    """Brokers with a failed account whose order may be live: may-exist
    wording, or any failure that does not positively say nothing was sent
    (a module that raised after sending)."""
    out = []
    for r in results or []:
        failed = [a for a in (r.get("accounts") or [])
                  if isinstance(a, dict) and not a.get("ok")]
        texts = _failed_texts(r)
        if not failed and not texts:
            continue
        risky = any(_account_order_may_exist(a) for a in failed) or any(
            not _mirror_account_unsent(a)
            and not any(w in str(a.get("message") or "").lower()
                        for w in _MIRROR_PERMANENT_FAILURE)
            for a in failed)
        if not failed:
            risky = not all(_nothing_was_sent(t) or _LOGIN_N_REFUSED.search(t)
                            for t in texts)
        if risky:
            out.append(str(r.get("broker") or ""))
    return [b for b in out if b]


def _mirror_permanent_refusal(results) -> bool:
    """Any leg the broker refused for good (_MIRROR_PERMANENT_FAILURE): a
    re-send of the whole pick would only be refused again there."""
    texts = " | ".join(t for r in (results or []) for t in _failed_texts(r)).lower()
    return any(w in texts for w in _MIRROR_PERMANENT_FAILURE)


def _mirror_release_owed(app, wedged) -> None:
    """Queue each owed pick whose broker is no longer wedged, for that
    broker only. The record stays until the launch (or a skip) clears it,
    so switching mirror off, or a restart, does not lose it."""
    owed = _mirror_owed_list(app)
    if not owed:
        return
    queued = {(str(p.get("_only") or ""), str(p.get("symbol") or "").upper(),
               str(p.get("date") or "")) for p in app._mirror_queue}
    now = datetime.now().isoformat(timespec="seconds")
    for o in list(owed):
        b = o.get("broker")
        if not b or b in (wedged or ()):
            continue
        if (b, o.get("symbol"), o.get("date")) in queued:
            continue
        if str(o.get("after") or "") > now:
            continue                    # a failed leg's back-off; a later check sends it
        entry = {
            "symbol": o.get("symbol"), "date": o.get("date"),
            "note": o.get("note"), "_only": b, "_when": "owed",
            "_trigger": "owed", "_attempts": str(o.get("attempts") or "0")}
        if o.get("last_buy"):
            entry["last_buy"] = o["last_buy"]
        if o.get("accounts"):
            entry["_accounts"] = list(o["accounts"])
        app._mirror_queue.append(entry)
        if o.get("attempts"):
            app._mirror_log_msg(f"{o.get('symbol')}: retrying the buy at {b} "
                                f"(nothing was sent there last time)")
        else:
            app._mirror_log_msg(f"{o.get('symbol')}: {b} is back — sending the "
                                f"buy it missed")


def _task_brokers_in_flight(task, in_flight) -> List[str]:
    """App keys of `task`'s brokers that a live batch still has an order out at
    -- or whose hung, written-off leg still holds the browser
    (_hung_browser_brokers): a sell sent there only waits out the lock."""
    keys = {lifecycle.app_key(b) for b in (getattr(task, "brokers", None) or ())}
    return sorted(keys & (set(in_flight or ()) | _hung_browser_brokers()))


def _cap_text(qty: float) -> str:
    """A cap as the Decimal string public.execute_trade takes -- never '1e-05'."""
    try:
        return lifecycle.qty_text(Decimal(repr(round(float(qty), 8))))
    except (InvalidOperation, ValueError, TypeError):
        return "0"


def _public_sell_plan(holdings, caps: Dict[str, float],
                      remnant_only: bool = False) -> Dict[str, Any]:
    """What a holdings-sized Public sell will do, from a resolve-time read.

    The same rule public.execute_trade applies at order time -- min(held,
    cap), skip accounts with no cap, and under `remnant_only` skip whole
    shares -- run against the balances lifecycle.resolve just read, so the
    confirm dialog can say what is about to happen instead of printing one
    quantity that no Public account is actually going to send.
    """
    sell: List[tuple] = []
    not_ours = whole = 0
    for label, held in holdings or ():
        cap = caps.get(str(label).split(" = ")[0].strip())
        if not cap:
            not_ours += 1
            continue
        if remnant_only and held >= 1:
            whole += 1
            continue
        q = min(float(held), float(cap))
        if q > 1e-9:
            sell.append((label, q))
    return {"sell": sell, "not_ours": not_ours, "whole": whole}


def _public_plan_text(plan: Dict[str, Any]) -> str:
    """One line for the confirm dialog, e.g.
    'sells what each account holds, up to what RSAMAXXED bought there —
    21 accounts, 0.0333 each'."""
    sell = plan.get("sell") or []
    head = "sells what each account holds, up to what RSAMAXXED bought there"
    if sell:
        lo = min(q for _a, q in sell)
        hi = max(q for _a, q in sell)
        each = (f"{_qty_text(lo)} each" if hi - lo < 1e-9
                else f"{_qty_text(lo)}–{_qty_text(hi)} each")
        body = f"{head} — {_plural(len(sell), 'account')}, {each}"
    else:
        body = f"{head} — nothing to sell"
    extra = []
    if plan.get("not_ours"):
        extra.append(f"{_plural(plan['not_ours'], 'account')} not bought "
                     f"through RSAMAXXED, skipped")
    if plan.get("whole"):
        extra.append(f"{_plural(plan['whole'], 'account')} holding a whole "
                     f"share wait for their own exit")
    return body + ("" if not extra else " · " + " · ".join(extra))


def _plural(n, word: str, many: Optional[str] = None) -> str:
    """'1 account', '3 accounts' -- the '(s)' the UI used to print everywhere.

    `n` may be a number or already-formatted text ('0.98', '1'), since share
    counts reach the UI through _qty_text: it is printed as given and only
    exactly one takes the singular.
    """
    try:
        one = abs(float(str(n).replace(",", "")) - 1) < 1e-9
    except (TypeError, ValueError):
        one = False
    return f"{n} {word if one else (many or word + 's')}"


def _money_signed(value, decimals: int = 2) -> str:
    """+$3,728.34 / -$12.50: the sign before the dollar sign, as money is
    written. f"${x:+,.2f}" produced "$+3,728.34", which reads as a typo on
    exactly the figures the app is proudest of (realized P/L)."""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return str(value)
    sign = "-" if v < 0 and round(abs(v), decimals) != 0 else "+"
    return f"{sign}${abs(v):,.{int(decimals)}f}"


def _money(value, decimals: int = 2) -> str:
    """$1,234.50 / -$12.50 -- unsigned for positives, and the minus before
    the dollar sign for negatives rather than "$-12.50" (chart axes and the
    average loss, which are the figures that go below zero)."""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return str(value)
    neg = v < 0 and round(abs(v), decimals) != 0
    return f"{'-' if neg else ''}${abs(v):,.{int(decimals)}f}"


def _nothing_to_sell(result: Dict[str, Any]) -> bool:
    """A broker leg that placed no order because no account had anything of
    ours to sell -- an answer, not a failure. Public's holdings-sized sell is
    the one that produces it: every account read, every one skipped."""
    return (not result.get("ok_accounts") and not result.get("fail_accounts")
            and not result.get("errors") and bool(result.get("skipped")))


def _skip_note(skipped: Dict[str, int]) -> str:
    """{'whole': 18, 'none': 3} -> '21 skipped (18 whole shares wait for their
    own exit, 3 hold none)'."""
    skipped = skipped or {}
    n = sum(int(v or 0) for v in skipped.values())
    why = []
    if skipped.get("whole"):
        k = skipped["whole"]
        why.append(f"{_plural(k, 'whole share')} wait{'s' if k == 1 else ''} "
                   f"for {'its' if k == 1 else 'their'} own exit")
    if skipped.get("none"):
        k = skipped["none"]
        why.append(f"{k} hold{'s' if k == 1 else ''} none")
    if skipped.get("not_ours"):
        why.append(f"{skipped['not_ours']} not bought through RSAMAXXED or "
                   f"already sold")
    return f"{n} skipped" + (f" ({', '.join(why)})" if why else "")


#: Symbols the round-up radar has already announced (see _check_roundup_radar).
ROUNDUP_RADAR_FILE = ROOT_DIR / "roundup_radar.json"


def _load_roundup_flagged() -> set:
    data = atomic.load_state(ROUNDUP_RADAR_FILE, [])
    return {str(s).upper() for s in data} if isinstance(data, list) else set()


def _save_roundup_flagged(symbols) -> None:
    try:
        _write_json(ROUNDUP_RADAR_FILE, sorted(symbols))
    except OSError:
        pass


#: Plays whose Public late-round-up check is settled: SYMBOL -> the date an
#: exit-time read of Public found nothing left to sell. See _sell_plays.
PUBLIC_LATE_CHECKED_FILE = ROOT_DIR / "public_late_checked.json"


def _load_public_late_checked() -> Dict[str, str]:
    data = atomic.load_state(PUBLIC_LATE_CHECKED_FILE, {})
    return {str(k).upper(): str(v) for k, v in data.items()} if isinstance(data, dict) else {}


def _mark_public_late_checked(symbols, day: Optional[str] = None) -> None:
    """Record that Public was read at exit time and there is nothing more to
    take on these plays, so a late-round-up leg stops offering itself.

    A marker file rather than a journal row, on purpose. A close row would
    also end it, but a close carries cost basis into `unaccounted()` -- and
    these shares are already fully accounted for by the fractional sell that
    split_adjusted restated. Nothing about P/L should change because we looked
    and found nothing. A LATER exit called at Public reopens the leg on its
    own, because the check is dated and an exit dated after it outranks it.
    """
    day = day or date.today().isoformat()
    data = _load_public_late_checked()
    for s in symbols:
        s = str(s or "").upper()
        if s and day >= data.get(s, ""):
            data[s] = day
    try:
        _write_json(PUBLIC_LATE_CHECKED_FILE, data)
    except OSError:
        pass


def _spread_over_accounts(accounts: List[tuple], qty: float) -> List[tuple]:
    """Split `qty` shares across open accounts, filling each before the next.

    Whole accounts first so the common case — "all of it" — writes one clean
    row per account rather than an even smear that leaves every account holding
    an odd fraction of a share.
    """
    out: List[tuple] = []
    left = float(qty)
    for acct, have in accounts:
        if left <= 1e-9:
            break
        take = min(have, left)
        out.append((acct, take))
        left -= take
    return out


def _iso_at_noon(date_str: str) -> Optional[str]:
    """'2026-08-18' -> an ISO timestamp on that day, or None if unparseable.

    Noon UTC, not midnight: every date in this app is the first ten characters
    of the timestamp, and midnight UTC is the previous evening in every US time
    zone, so a sale reported for the 18th would file itself under the 17th.
    """
    try:
        d = datetime.strptime(str(date_str).strip(), "%Y-%m-%d")
    except (TypeError, ValueError):
        return None
    return d.replace(hour=12, tzinfo=timezone.utc).isoformat()


def _sell_plays(sells: List[Dict[str, Any]],
                renames: Optional[Dict[str, str]] = None) -> List[SellPlay]:
    """Fold the exit feed and the journal into one row per ticker.

    A brokerage appears on a play if we ever bought there OR an exit named it,
    so "you hold this at four more brokers and nobody has called them yet" is
    visible instead of implied by absence.

    `renames` is CURRENT ticker -> the one we bought under (App._symbol_renames).
    A renamed play is one row under the current ticker, netted against the
    journal of BOTH names: AGAE was bought, AIFA is what the exit names and what
    the broker will sell, and looking the journal up under AIFA alone read the
    position as never held — "no position" on shares we own.
    """
    renames = {str(k).upper(): str(v).upper()
               for k, v in (renames or {}).items() if k and v}
    current_of = {old: new for new, old in renames.items() if old != new}

    def names_of(sym: str) -> tuple:
        old = renames.get(sym)
        return (sym, old) if old and old != sym else (sym,)

    ledger = _sell_share_ledger(renames)
    attempts = _load_trade_attempts()

    called: Dict[str, Dict[str, str]] = {}      # SYM -> broker -> newest date
    price: Dict[str, Any] = {}
    newest: Dict[str, str] = {}
    for sl in sells:
        sym = str(sl.get("symbol") or "").upper()
        if not sym:
            continue
        # An exit called under the old name is the same play.
        sym = current_of.get(sym, sym)
        when = str(sl.get("sell_date") or "")
        posted = str(sl.get("posted_at") or "")
        if posted >= newest.get(sym, ""):
            newest[sym] = posted
            price[sym] = sl.get("exit_price")
        for key in _sell_leg_broker_keys(sl):
            if when >= called.setdefault(sym, {}).get(key, ""):
                called[sym][key] = when

    plays: List[SellPlay] = []
    late_checked: Optional[Dict[str, str]] = None     # loaded only if needed
    for sym in sorted(called.keys() | newest.keys()):
        names = names_of(sym)
        brokers = sorted({b for (b, s) in ledger if s in names} | set(called.get(sym, {})))
        legs = []
        for b in brokers:
            bought = sum(ledger.get((b, n), [0.0, 0.0])[0] for n in names)
            sold = sum(ledger.get((b, n), [0.0, 0.0])[1] for n in names)
            left = max(0.0, bought - sold)
            empty = bought <= 1e-9 and sold <= 1e-9
            if empty and b not in called.get(sym, {}):
                # A zero-quantity row and nobody called it: nothing to say.
                continue
            if empty:
                # The exit named a brokerage we never got into. REPORTED, not
                # dropped: dropping it was read as "no exit has been called",
                # which is the exact opposite of what happened. GCTK and ARTL
                # were called at Chase on 2026-08-31, all four Chase accounts
                # had rejected the buy ("pending a corporate action"), so the
                # only trace of the exit vanished and the card said the play
                # was quietly waiting. It is not SELL_DONE either — that
                # claimed an exit nobody took.
                state = SELL_NONE
            elif left <= 1e-9:
                state = SELL_DONE
                # PUBLIC'S LATE ROUND-UP. Public can credit 0.2 of a share
                # after a split and round the account up to 0.98 days or weeks
                # later. Sell the 0.2 first and the split-adjusted ledger calls
                # the leg closed -- correctly for P/L, and blind to the 0.98
                # that arrives afterwards. So when an exit is called AT Public
                # and the RAW journal still shows part of what we bought there
                # unsold, the leg is offered again; the live read at sell time
                # decides whether anything is actually there. Nothing else
                # widens: without an exit at Public it stays done, and once an
                # exit-time read has found nothing it stays done until a newer
                # exit is called. See _public_sell_caps and
                # _mark_public_late_checked.
                when = called.get(sym, {}).get(b, "")
                if b == "public" and when:
                    if late_checked is None:
                        late_checked = _load_public_late_checked()
                    if (late_checked.get(sym, "") < when[:10]
                            and _public_sell_caps(names)):
                        state = SELL_NOW
            elif b in called.get(sym, {}):
                state = SELL_NOW
            else:
                state = SELL_WAIT
            # On a leg we hold, SELL rejections only: a buy that failed months
            # ago says nothing about whether we can get out, and reporting it
            # read as "this exit was rejected" on a broker never asked. On a
            # leg we never got into, that failed BUY is the whole story — it is
            # the answer to "why do I hold none here".
            want = "buy" if state == SELL_NONE else "sell"
            bad = [r for (s2, b2, _a), r in attempts.items()
                   if s2 in names and b2 == b and not r.get("ok")
                   and r.get("side") == want]
            legs.append(SellLeg(
                broker=b, bought=bought, sold=sold, left=left, state=state,
                alert_date=called.get(sym, {}).get(b, ""),
                failed_accounts=len(bad) if state != SELL_DONE else 0,
                fail_reason=_tidy_reason(bad[0].get("msg", ""), 90) if bad else ""))
        plays.append(SellPlay(symbol=sym, exit_price=price.get(sym),
                              legs=tuple(legs), last_alert=newest.get(sym, "")))
    # Worklist order: most money ready to sell first, then most recently called.
    plays.sort(key=lambda p: (-p.ready_value, p.last_alert and -ord(p.last_alert[0])))
    plays.sort(key=lambda p: p.last_alert, reverse=True)
    plays.sort(key=lambda p: p.ready_value, reverse=True)
    return plays


SELLS_CONFIRMED_FILE = ROOT_DIR / "sells_confirmed.json"


def _sell_play_key(play) -> str:
    """One closed play's identity, for the confirmed-and-hidden list.

    The newest exit's timestamp is part of it on purpose. A ticker can come
    back around for a second reverse split months later, and keying on the
    symbol alone would silently swallow that second play — the user would tick
    off BYAH once in July and never be shown the September exit at all.
    """
    return f"{play.symbol.upper()}:{play.last_alert or ''}"


def _load_confirmed_sells() -> set:
    """Closed plays the user has ticked off, so they stop taking up room.

    Closed is the one bucket that only ever grows: every play we finish stays
    on the board forever, and after a couple of months the section you act on
    is buried under months of plays you are done with. Confirming is a display
    decision and nothing else — no journal row is touched, no position is
    changed, and unhiding puts it straight back.
    """
    data = atomic.load_state(SELLS_CONFIRMED_FILE, [])
    return {str(k) for k in data} if isinstance(data, list) else set()


def _save_confirmed_sells(keys: set) -> None:
    try:
        _write_json(SELLS_CONFIRMED_FILE, sorted(keys))
    except OSError:
        pass


def _sellnow_tasks(sells: List[Dict[str, Any]],
                   renames: Optional[Dict[str, str]] = None) -> List[Any]:
    """The Sell-now board, as things auto-sell can actually place.

    THIS IS THE WHOLE EXIT RULE, and it is deliberately the same one the Sell
    now tab renders: an exit has been called at a brokerage, and the journal
    still shows shares open there. Nothing else qualifies.

    It replaces a worklist built out of the TRACK board's split classification
    — `became_fractional`, `status == "rounded_up"` — which was answering a
    different question than the one being asked. That board says what a SPLIT
    did; it does not say we were told to get out, and it does not say we are
    still in. So it sold positions no exit had been called on, and sat on ones
    that had: an exit at Public on a play the board still called "pending" was
    invisible to auto-sell, while every fractional remnant went out the door
    whether or not anyone had said to sell it. The two lists agreed often
    enough to look right and disagreed exactly where it mattered.

    One task per PLAY carrying every ready brokerage, because `execute_trade`
    fans one quantity across a broker's own accounts and `lifecycle.resolve`
    already takes a broker tuple. Brokers this copy cannot trade are dropped
    here rather than failing later — an exit called at Chase on a machine with
    no Chase credentials is not our order to place.
    """
    renames = renames or {}
    out: List[Any] = []
    for play in _sell_plays(sells, renames):
        task = _sellnow_task(play, renames=renames)
        if task is not None:
            out.append(task)
    # Biggest ready position first: if the cap or the market close cuts the run
    # short, the money that was left behind should be the smallest.
    out.sort(key=lambda t: t.accounts, reverse=True)
    return out


def _sellnow_task(play, legs=None, renames: Optional[Dict[str, str]] = None):
    """One play's ready legs as a SellTask, or None if none are placeable.

    `legs` narrows it to a subset of the play's SELL_NOW legs — that is what
    lets a single brokerage be queued on its own while the rest of the play
    waits. Default is every ready leg, which is what auto-sell and the sweep
    want.
    """
    renames = renames or {}
    ready = tuple(legs) if legs is not None else play.of(SELL_NOW)
    if not ready:
        return None

    alert_symbol = renames.get(play.symbol.upper(), play.symbol)
    names = tuple(dict.fromkeys((play.symbol, alert_symbol)))
    brokers: List[str] = []
    accounts = 0
    newest = ""
    for leg in ready:
        if lifecycle.app_key(leg.broker) not in BROKER_MODULES:
            continue
        brokers.append(rsa_feed.normalize_broker(leg.broker))
        n = len(_leg_open_accounts(leg.broker, names))
        if lifecycle.app_key(leg.broker) == "public":
            # A late round-up leg is closed in the adjusted ledger and still
            # open in the raw one; count the accounts it will actually read.
            n = max(n, len(_public_sell_caps(names)))
        accounts += n
        newest = max(newest, leg.alert_date or "")
    if not brokers:
        return None

    return lifecycle.SellTask(
        symbol=play.symbol,
        # The journal may still know this position by its pre-split ticker.
        # lifecycle.resolve looks under both, so handing it only the new name
        # is how a renamed play reads as "no position anywhere".
        alert_symbol=alert_symbol,
        alert_date=newest or play.last_alert[:10],
        status="exit_called",
        brokers=tuple(dict.fromkeys(brokers)),
        accounts=accounts,
        skipped_brokers=tuple(
            rsa_feed.normalize_broker(l.broker) for l in ready
            if lifecycle.app_key(l.broker) not in BROKER_MODULES),
    )


#: SellTask.status for a Public remnant cleared on the back of an exit called
#: elsewhere. _exit_fire reads it to send Public `remnant_only`.
REMNANT_STATUS = "remnant"

#: Whether auto-sell clears Public fractions on the back of an exit called at
#: ANOTHER brokerage (_public_remnant_tasks). OFF, pending the owner's call.
#:
#: Public does not always settle a split at once: it can credit 0.2 of a share
#: and round the account up to 0.98 days or weeks later. An exit called at
#: Robinhood says nothing about whether Public has finished, so selling the
#: fraction the moment it is called elsewhere can sell 0.2 now and leave the
#: round-up to arrive into a play we have already walked away from. The code
#: and its tests stay; flipping this to True turns it back on.
#:
#: This guards ONLY that addition. The TRACK board's own `fractional` plays
#: (lifecycle.sell_worklist) keep clearing Public leftovers whenever the
#: fractionals toggle is on, exactly as before.
PUBLIC_REMNANT_CLEAR = False


def _public_remnant_tasks(plays, renames: Optional[Dict[str, str]] = None) -> List[Any]:
    """Public fractions left behind on plays whose exit was called elsewhere.

    IPDN, 2026-09-24: the exit named Robinhood and Schwab, where the split
    rounded up to a whole share. Public returned 1/30 of a share instead, so
    the exit never named it -- and nothing else ever would. The Sell-now path
    only sells brokerages an exit names, and the fractional path only sees
    plays the TRACK board calls `fractional`, which a play that rounded up
    somewhere is not. 21 accounts of IPDN sat at Public with no path out.

    The rule is narrow on purpose. An exit must have been called on the play
    at some brokerage (the play is over), Public must still be open in the
    journal and not itself named, and Public is sent `remnant_only`: it reads
    every account live and sells only balances under one share. A whole share
    at Public is a position that waits for its own exit, never collateral.
    """
    if not PUBLIC_REMNANT_CLEAR or "public" not in BROKER_MODULES:
        return []                       # see PUBLIC_REMNANT_CLEAR
    renames = renames or {}
    out: List[Any] = []
    for play in plays:
        called = [l.alert_date for l in play.legs
                  if l.alert_date and lifecycle.app_key(l.broker) != "public"]
        if not called:
            continue
        waiting = [l for l in play.legs
                   if lifecycle.app_key(l.broker) == "public" and l.state == SELL_WAIT]
        if not waiting:
            continue
        out.append(lifecycle.SellTask(
            symbol=play.symbol,
            alert_symbol=renames.get(play.symbol.upper(), play.symbol),
            alert_date=max(called),
            status=REMNANT_STATUS,
            brokers=("Public",),
            accounts=len(_leg_open_accounts(waiting[0].broker, play.symbol)),
        ))
    return out


PICKS_FILE = ROOT_DIR / "picks.json"

# Picks auto-expire this many days after their alert date — stale RSA alerts are
# removed automatically on load (locally + pushed back to the shared remote).
# A pick we actually BOUGHT is exempt: it is no longer an alert, it is a record
# of an open RSA position, and the Purchased tab is the only place it lives.
PICK_MAX_AGE_DAYS = 4


# How far back to look when working out how many accounts we actually
# trade. Long enough to survive a quiet week, short enough to drop
# accounts that were renamed or closed.
ACCOUNT_UNIVERSE_WINDOW_DAYS = 60


PICKS_DONE_FILE = ROOT_DIR / "picks_done.json"


def _load_done_picks() -> set:
    """(SYMBOL, date) for picks the user has manually called finished.

    Coverage can't always reach 100%: a broker may be down, an account may be
    restricted, or a name may simply be unbuyable somewhere. Without a manual
    override such a pick would sit in Partial forever.
    """
    data = atomic.load_state(PICKS_DONE_FILE, [])
    out = set()
    for row in data if isinstance(data, list) else []:
        if isinstance(row, (list, tuple)) and len(row) == 2:
            out.add((str(row[0]).upper(), str(row[1])))
    return out


def _save_done_picks(keys: set) -> None:
    try:
        _write_json(PICKS_DONE_FILE, sorted([list(k) for k in keys]))
    except OSError:
        pass


COVERAGE_READ_FILE = ROOT_DIR / "coverage_read.json"


def _coverage_fingerprint(rows: List[tuple]) -> str:
    """Identity of a set of coverage warnings — their text, not their presence.

    Keyed on the wording because the wording carries the numbers: a new symbol,
    a changed dollar amount, or one more unpriced buy all produce a different
    fingerprint. That is the point of dismissing by content rather than by a
    plain hidden/shown flag.
    """
    joined = "\n".join(text for _colour, text in rows)
    return hashlib.sha256(joined.encode("utf-8")).hexdigest()


def _load_coverage_read() -> str:
    data = atomic.load_state(COVERAGE_READ_FILE, {})
    return str(data.get("fingerprint", "")) if isinstance(data, dict) else ""


def _save_coverage_read(fingerprint: str) -> None:
    try:
        _write_json(COVERAGE_READ_FILE, {"fingerprint": fingerprint})
    except OSError:
        pass


TRADE_RESULTS_LOG = ROOT_DIR / "logs" / "trade_results.log"

_TRADE_HEAD_RE = re.compile(
    r"^\[(?P<ts>[\d\-]+ [\d:]+)\]\s+(?P<side>BUY|SELL)\s+\S+\s+(?P<sym>\S+)\s+on\s+"
    r"(?P<broker>\S+)\s*->", re.I)
_TRADE_ROW_RE = re.compile(r"^\s+\[(?P<st>OK|FAIL)\]\s+(?P<acct>.+?):\s*(?P<msg>.*)$")
_ACCT_NUM_RE = re.compile(r"\(([^)]+)\)\s*$")

_trade_attempts_cache: Dict[str, Any] = {"mtime": None, "data": {}}


def _account_key(label: str) -> str:
    """Stable identity for an account across the journal and the trade log.

    The human label drifts — encoding damage ('Fidelity 1 � ETFs'), renames,
    different masking per broker — but the trailing "(number)" does not, so
    match on that.
    """
    label = str(label or "").strip()
    m = _ACCT_NUM_RE.search(label)
    raw = m.group(1) if m else label
    return "".join(c for c in raw if c.isalnum()).upper().lstrip("*") or label.upper()


def _load_trade_attempts() -> Dict[tuple, Dict[str, Any]]:
    """(SYMBOL, broker, account_key) -> {ok, msg, ts, label} from the trade log.

    Failures are not recorded in the journal (only fills are), so this log is
    the only place that remembers *why* an account did not get filled.
    """
    try:
        mtime = TRADE_RESULTS_LOG.stat().st_mtime
    except OSError:
        return {}
    if _trade_attempts_cache["mtime"] == mtime:
        return _trade_attempts_cache["data"]

    out: Dict[tuple, Dict[str, Any]] = {}
    sym = broker = ts = side = None
    try:
        text = TRADE_RESULTS_LOG.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}
    for line in text.splitlines():
        head = _TRADE_HEAD_RE.match(line)
        if head:
            sym = head.group("sym").upper()
            broker = head.group("broker").lower()
            ts = head.group("ts")
            side = head.group("side").lower()
            continue
        row = _TRADE_ROW_RE.match(line)
        if row and sym:
            # Later entries win: a retry that succeeded should not keep showing
            # the earlier rejection.
            out[(sym, broker, _account_key(row.group("acct")))] = {
                "ok": row.group("st") == "OK",
                "msg": row.group("msg").strip(),
                "ts": ts,
                "side": side or "",
                "label": row.group("acct").strip(),
            }
    _trade_attempts_cache["mtime"] = mtime
    _trade_attempts_cache["data"] = out
    return out


def _universe_accounts() -> List[tuple]:
    """(broker, account_id) for every account we have traded recently."""
    from datetime import timedelta
    cutoff = (datetime.now() - timedelta(days=ACCOUNT_UNIVERSE_WINDOW_DAYS)
              ).strftime("%Y-%m-%d")
    try:
        rows = trade_journal.get_trades()
    except Exception:
        return []
    return sorted({(str(t.get("broker") or ""), str(t.get("account_id") or ""))
                   for t in rows if t.get("side") == "buy"
                   and str(t.get("timestamp") or "")[:10] >= cutoff})


def _pick_missing_accounts(symbol: str, pick_date: str) -> List[Dict[str, str]]:
    """Accounts with no confirmed buy of this pick, and why — newest reason wins.

    status is 'failed' when the trade log has a rejection for that account and
    symbol, otherwise 'not attempted'.
    """
    symbol = str(symbol or "").upper()
    bought = set()
    try:
        for t in trade_journal.get_trades():
            if (t.get("side") == "buy"
                    and str(t.get("symbol") or "").upper() == symbol
                    and str(t.get("timestamp") or "")[:10] >= str(pick_date)):
                bought.add((str(t.get("broker") or ""), str(t.get("account_id") or "")))
    except Exception:
        return []

    attempts = _load_trade_attempts()
    missing: List[Dict[str, str]] = []
    for broker, acct in _universe_accounts():
        if (broker, acct) in bought:
            continue
        rec = attempts.get((symbol, broker, _account_key(acct)))
        if rec and not rec.get("ok"):
            missing.append({"broker": broker, "account": acct,
                            "status": "failed", "reason": str(rec.get("msg") or "")})
        else:
            missing.append({"broker": broker, "account": acct,
                            "status": "not attempted", "reason": ""})
    return missing


def _tidy_reason(msg: str, limit: int = 150) -> str:
    """Squeeze a broker rejection into one readable line."""
    msg = re.sub(r"\s+", " ", str(msg or "")).strip()
    # Public wraps the useful part in a JSON blob.
    m = re.search(r'"message"\s*:\s*"([^"]+)"', msg)
    if m:
        msg = m.group(1)
    msg = re.sub(r"^(Skipped|Order failed|Preview failed)\s*:\s*", "", msg, flags=re.I)
    msg = re.sub(r"^.*?HARD Error for \w+\s*:\s*(Error:)?\s*", "", msg, flags=re.I)
    return msg[:limit] + ("…" if len(msg) > limit else "")


def _observed_account_counts() -> Dict[str, int]:
    """broker -> distinct accounts with a confirmed buy in the trailing window.

    The same (broker, account_id) set the coverage numerator counts, so a
    denominator built from it can never fall below what a pick can score.
    Recent buys only: over all time the journal also holds accounts that were
    since renamed or closed (Wells Fargo shows 20 distinct labels for 10 real
    accounts), and that inflated denominator means no pick ever reads as fully
    bought. Memoised per (journal version, day) — it is a pass over every trade.
    """
    key = (trade_journal.version(), id(trade_journal.get_trades), date.today())
    hit = _COVERAGE_MEMO.get("observed")
    if hit is not None and hit[0] == key:
        return hit[1]
    out: Dict[str, int] = {}
    try:
        cutoff = (datetime.now() - timedelta(days=ACCOUNT_UNIVERSE_WINDOW_DAYS)
                  ).strftime("%Y-%m-%d")
        seen = {(str(t.get("broker") or ""), str(t.get("account_id") or ""))
                for t in trade_journal.get_trades()
                if t.get("side") == "buy"
                and str(t.get("timestamp") or "")[:10] >= cutoff}
        for broker, _acct in seen:
            if broker:
                out[broker] = out.get(broker, 0) + 1
    except Exception:
        out = {}
    _COVERAGE_MEMO["observed"] = (key, out)
    return out


# balances.json keys an account by its label, and some brokers put the balance
# IN the label ("WELLSTRADE (****1234) = $5.00"), so one account gathers a new
# row every time its cash moves. Only the rows from the latest refresh count,
# and they are compared with the balance cut off.
_BALANCE_SUFFIX_RE = re.compile(r"\s*=\s*-?\$?[\d,.]+\s*$")
_REFRESH_WINDOW_S = 120


def _balances_account_counts() -> Dict[str, int]:
    """broker -> accounts returned by the latest holdings refresh on record.

    balances.json is written by every Refresh All, so it is the one place a
    broker's account count survives a restart before anything has been bought
    there. Stale by nature — callers treat it as a floor, never an answer.
    """
    key = balances.version()
    hit = _COVERAGE_MEMO.get("balances")
    if hit is not None and hit[0] == key:
        return hit[1]
    out: Dict[str, int] = {}
    try:
        for broker, book in (balances.load().get("brokers") or {}).items():
            stamped = []
            for acct_id, row in (book or {}).items():
                try:
                    at = datetime.fromisoformat(str((row or {}).get("seen_at") or ""))
                except ValueError:
                    continue
                stamped.append((at, acct_id))
            if not stamped:
                continue
            latest = max(at for at, _ in stamped)
            fresh = {_BALANCE_SUFFIX_RE.sub("", str(a)).strip()
                     for at, a in stamped
                     if (latest - at).total_seconds() <= _REFRESH_WINDOW_S}
            if fresh:
                out[str(broker)] = len(fresh)
    except Exception:
        out = {}
    _COVERAGE_MEMO["balances"] = (key, out)
    return out


def _account_count_evidence() -> Dict[str, int]:
    """broker -> how many accounts we have actual EVIDENCE for (absent = none).

    This session's live count wins when a bootstrap or refresh has succeeded —
    it is what the broker says right now. Before that, the larger of the last
    refresh on record and what the journal has seen bought. Nothing here is a
    guess.
    """
    observed = _observed_account_counts()
    stored = _balances_account_counts()
    out: Dict[str, int] = {}
    for broker in set(observed) | set(stored) | set(_LIVE_ACCOUNT_COUNTS):
        live = _LIVE_ACCOUNT_COUNTS.get(broker)
        n = live if live is not None else max(stored.get(broker, 0),
                                              observed.get(broker, 0))
        if n > 0:
            out[broker] = n
    return out


def _account_counts_by_broker() -> Dict[str, int]:
    """Linked broker -> how many accounts it holds, for the dashboard's
    ACCOUNTS figure, the status rows and the order estimate.

    A linked broker we know nothing about yet counts as ONE account: it is at
    least one, and anything larger would be a number made up for someone
    else's fleet.
    """
    evidence = _account_count_evidence()
    return {b: max(1, evidence.get(b, 0))
            for b in BROKER_MODULES if _broker_has_creds(b)}


def _tradable_account_counts() -> Dict[str, int]:
    """Linked broker -> accounts a pick has to reach there to count as fully
    bought — the per-broker coverage denominator.

    When the broker has reported its accounts THIS session, the larger of that
    live count and the accounts the journal has seen bought. Trusting the
    journal alone read a broker listing 3 accounts, only 1 of them ever
    bought, as fully covered — the other two were silently never owed
    anything. The journal still sets a floor, so a bar can never read 12/10
    (the numerator counts the same (broker, account) set). An account that
    really is never bought into (a joint account, a spare sub-account) now
    keeps its picks in Partial; "Mark done" is how the user clears those.

    With no live count yet (fresh start, broker not bootstrapped), the journal
    comes first as before, then the last refresh on record, then one — a
    stale stored count is not trusted over what was actually bought.
    """
    observed = _observed_account_counts()
    evidence = _account_count_evidence()
    out: Dict[str, int] = {}
    for b in BROKER_MODULES:
        if not _broker_has_creds(b):
            continue
        live = _LIVE_ACCOUNT_COUNTS.get(b)
        if live:
            out[b] = max(observed.get(b, 0), int(live))
        else:
            out[b] = observed.get(b) or evidence.get(b) or 1
    return out


def _account_universe_static() -> int:
    """Total accounts we can buy into — the coverage denominator, computed
    without a live App instance.

    A too-small denominator makes a half-filled pick look complete, and a
    too-large one strands every pick in Partial. So it is built only from what
    this user's own journal and brokers have shown (see
    _tradable_account_counts), never from a fixed table.
    """
    return sum(_tradable_account_counts().values())


# (what it was computed from) -> result, for the two journal scans below. One
# render of the Command Center asked for coverage five times over (purchased,
# partial = touched - fully covered, the pipeline strip...), each a pass over
# every trade in the journal. The answer only changes when the journal or the
# pick list does, so it is computed once per (journal version, picks).
_COVERAGE_MEMO: Dict[str, tuple] = {}


def _memo_key(picks: List[Dict[str, str]]) -> tuple:
    return (trade_journal.version(), id(trade_journal.get_trades),
            tuple((str(p.get("symbol") or "").upper(), str(p.get("date") or ""))
                  for p in picks))


def _pick_coverage(picks: List[Dict[str, str]]) -> Dict[tuple, int]:
    """(SYMBOL, pick_date) -> how many distinct accounts hold a confirmed buy.

    A buy counts toward a pick when it is dated on or after the alert date.
    Counting *accounts* (broker + account_id) rather than brokers is what makes
    "bought on 7 of 22" mean something when one broker holds ten accounts.

    Memoised per journal version — callers must treat the result as read-only.
    """
    key = _memo_key(picks)
    hit = _COVERAGE_MEMO.get("coverage")
    if hit is not None and hit[0] == key:
        return hit[1]
    cov = _pick_coverage_uncached(picks)
    _COVERAGE_MEMO["coverage"] = (key, cov)
    return cov


def _pick_coverage_uncached(picks: List[Dict[str, str]]) -> Dict[tuple, int]:
    cov: Dict[tuple, int] = {}
    try:
        all_trades = trade_journal.get_trades()
    except Exception:
        return cov
    buys: Dict[str, List[tuple]] = {}
    for t in all_trades:
        if t.get("side") != "buy":
            continue
        sym = str(t.get("symbol") or "").upper()
        if not sym:
            continue
        buys.setdefault(sym, []).append(
            (str(t.get("timestamp") or "")[:10],
             str(t.get("broker") or ""), str(t.get("account_id") or "")))
    for pick in picks:
        sym = str(pick.get("symbol") or "").upper()
        pick_date = str(pick.get("date") or "")
        if not sym or not pick_date:
            continue
        cov[(sym, pick_date)] = len({
            (b, a) for (d, b, a) in buys.get(sym, []) if d and d >= pick_date})
    return cov


#: A buy this many days BEFORE an alert still counts toward it. The feed
#: re-alerts the same split: SFWL alerted 2026-08-26 and again 2026-09-02, and
#: mirror bought a second share in every account on 09-03 because the 08-26
#: buys predated the new alert date.
MIRROR_REALERT_LOOKBACK_DAYS = 21
#: An OPEN lot blocks a broker only if it was bought within this many days
#: before the alert. Older open lots are leftovers of an earlier split of the
#: same ticker (a remnant never sold, a round-up the journal never closed) and
#: used to skip the broker for every new play on that name, forever.
MIRROR_OPEN_LOT_WINDOW_DAYS = 45


def _pick_broker_map(picks: List[Dict[str, str]]) -> Dict[tuple, set]:
    """(SYMBOL, pick_date) -> the brokers that already have this play.

    Keyed by broker rather than counted, because "has THIS broker already
    bought it" and "has anyone bought it" are different questions. Mirror needs
    the first: a name bought by hand at Chase says nothing about whether Public
    holds it.

    A broker has the play when either
      * the journal shows it still OPEN there (split-adjusted net buys > sells
        in any account) from a buy within MIRROR_OPEN_LOT_WINDOW_DAYS before
        the alert — an old open lot from an earlier split does not count, or
      * it bought the symbol on or after MIRROR_REALERT_LOOKBACK_DAYS before
        the alert date — a re-alert of a split we already bought into.
    A play months after the old one was sold off matches neither and buys.
    Mirror is the only caller; the Quick Picks coverage (_pick_coverage) is a
    separate, display-only rule.

    Memoised like _pick_coverage; the sets are shared, so never mutate them.
    """
    key = _memo_key(picks)
    hit = _COVERAGE_MEMO.get("brokers")
    if hit is not None and hit[0] == key:
        return hit[1]
    out = _pick_broker_map_uncached(picks)
    _COVERAGE_MEMO["brokers"] = (key, out)
    return out


def _pick_broker_map_uncached(picks: List[Dict[str, str]]) -> Dict[tuple, set]:
    out: Dict[tuple, set] = {}
    try:
        all_trades = trade_journal.get_trades()
    except Exception:
        return out
    buys: Dict[str, List[tuple]] = {}
    for t in all_trades:
        if t.get("side") != "buy":
            continue
        sym = str(t.get("symbol") or "").upper()
        if not sym:
            continue
        buys.setdefault(sym, []).append(
            (str(t.get("timestamp") or "")[:10], str(t.get("broker") or "")))

    # Open positions, per account, in pre-split shares — the same lens every
    # other position figure uses, so a sold split remnant nets to zero rather
    # than leaving 0.9 of a phantom share that would block the next play.
    net: Dict[tuple, float] = {}
    last_buy: Dict[tuple, str] = {}
    try:
        adjusted = trade_journal.split_adjusted(all_trades)
    except Exception:
        adjusted = []
    for t in adjusted:
        sym = str(t.get("symbol") or "").upper()
        broker = str(t.get("broker") or "")
        if not sym or not broker:
            continue
        try:
            qty = float(t.get("qty") or 0.0)
        except (TypeError, ValueError):
            continue
        side = str(t.get("side") or "").lower()
        # Per account number, not label: a buy and its sell under two labels
        # of one account must net to closed, not hold a phantom position.
        k = (sym, broker, _acct_net_key(broker, t.get("account_id")))
        if side == "buy":
            net[k] = net.get(k, 0.0) + qty
            d = str(t.get("timestamp") or "")[:10]
            if d > last_buy.get(k, ""):
                last_buy[k] = d
        elif side in ("sell", trade_journal.SIDE_CLOSE):
            net[k] = net.get(k, 0.0) - qty
    # sym -> [(broker, newest buy date of that open account)]
    open_at: Dict[str, List[tuple]] = {}
    for (sym, broker, acct), qty in net.items():
        if qty > 1e-9:
            open_at.setdefault(sym, []).append((broker, last_buy.get((sym, broker, acct), "")))

    for pick in picks:
        sym = str(pick.get("symbol") or "").upper()
        pick_date = str(pick.get("date") or "")
        if not sym or not pick_date:
            continue
        try:
            floor = (datetime.strptime(pick_date, "%Y-%m-%d").date()
                     - timedelta(days=MIRROR_REALERT_LOOKBACK_DAYS)).isoformat()
        except ValueError:
            floor = pick_date
        try:
            open_floor = (datetime.strptime(pick_date, "%Y-%m-%d").date()
                          - timedelta(days=MIRROR_OPEN_LOT_WINDOW_DAYS)).isoformat()
        except ValueError:
            open_floor = ""
        # An open lot with no readable buy date counts (fail closed).
        out[(sym, pick_date)] = ({b for (d, b) in buys.get(sym, [])
                                  if b and d and d >= floor}
                                 | {b for (b, d) in open_at.get(sym, [])
                                    if not d or d >= open_floor})
    return out


def _mirror_journal_problem() -> Optional[str]:
    """Why mirror must not trust the trade journal right now, or None.

    Every "already bought?" answer mirror gives comes from trades.json. When it
    can't be read, trade_journal serves the last rows it did read (or none),
    which is missing exactly the recent buys that stop a double-buy. So mirror
    fails CLOSED on any error the journal reports: unreadable, refused as
    truncated, or recovered but not trustworthy.

    A clean recovery from trades.bak is NOT an error (last_error() is None;
    last_recovery() says what happened): the .bak is refreshed after every
    save, so it is the last saved journal, and the recovered rows are written
    back. Pausing on it used to hold mirror until a restart.
    """
    try:
        trade_journal.get_trades()
    except Exception as e:                      # noqa: BLE001
        return f"trades.json could not be read ({e})"
    try:
        return trade_journal.last_error() or None
    except Exception as e:                      # noqa: BLE001
        return f"trades.json state unknown ({e})"


# The Partial and Purchased tabs are history as much as worklist, and they only
# grow: every pick ever bought lands there for good. Drawing all of it is what
# made clicking those tabs lag, and the rows you act on are the recent ones.
PICK_TAB_RECENT_DAYS = 14


def _split_recent_picks(picks: List[Dict[str, str]],
                        days: int = PICK_TAB_RECENT_DAYS,
                        today: Optional[date] = None) -> Tuple[list, list]:
    """(recent, older) by alert date. A pick whose date cannot be read counts
    as recent — hiding it behind "Show older" would lose it, and it cannot be
    aged honestly anyway."""
    today = today or date.today()
    floor = today - timedelta(days=days)
    recent: List[Dict[str, str]] = []
    older: List[Dict[str, str]] = []
    for p in picks:
        try:
            d = datetime.strptime(str(p.get("date") or ""), "%Y-%m-%d").date()
        except (ValueError, TypeError):
            recent.append(p)
            continue
        (recent if d >= floor else older).append(p)
    return recent, older


def _touched_pick_keys(picks: List[Dict[str, str]]) -> set:
    """Picks with at least one confirmed buy — i.e. real open positions.

    Used where losing the pick would lose history (stale-pick pruning, the
    local/remote merge). Deliberately NOT the Purchased test: a pick bought on
    one broker is still owed on the others.
    """
    return {k for k, n in _pick_coverage(picks).items() if n > 0}


def _purchased_pick_keys(picks: List[Dict[str, str]]) -> set:
    """(SYMBOL, pick_date) for every pick with a confirmed buy in the journal.

    Purchased is the *record* of what we have bought, so any confirmed buy puts
    a pick here. Gating this on full coverage instead emptied the tab, because
    one unreachable broker (Chase, SoFi) means nothing ever reaches 100%.
    Picks still owed accounts also appear under Partial, which is the
    actionable worklist; this tab is the history.
    """
    return _touched_pick_keys(picks) | (set(_pick_coverage(picks)) & _load_done_picks())


def _fully_covered_pick_keys(picks: List[Dict[str, str]]) -> set:
    """Picks held in every account we trade, or manually marked done."""
    universe = _account_universe_static()
    cov = _pick_coverage(picks)
    done = _load_done_picks()
    if universe <= 0:
        return {k for k, n in cov.items() if n > 0} | (set(cov) & done)
    return {k for k, n in cov.items() if n >= universe} | (set(cov) & done)


def _partial_pick_keys(picks: List[Dict[str, str]]) -> set:
    """Bought on some accounts but not all — the top-up worklist.

    Kept out of Quick Picks (which is only work not yet started) so a pick that
    mirror bought on one broker can't hide there, and surfaced separately from
    Purchased so it is obvious which positions still owe accounts.
    """
    return _touched_pick_keys(picks) - _fully_covered_pick_keys(picks)


def _pick_in_feed_window(p: Dict[str, str], max_age_days: int,
                         today: date) -> bool:
    """Still in the feed: at most `max_age_days` TRADING days old, or its own
    last day to buy hasn't passed (capped like the mirror's last_buy rule).

    Trading days, as the mirror counts them. By the calendar a Thursday alert
    was 6 days old the next Wednesday and was deleted here while the mirror,
    counting sessions, still had it at 4 and would have bought it."""
    age = _pick_trading_age(p, today)
    if age is None or age <= max_age_days:
        return True
    return (str(p.get("last_buy") or "")[:10] >= today.isoformat()
            and age <= MIRROR_LAST_BUY_MAX_AGE)


def _prune_stale_picks(picks: List[Dict[str, str]],
                       max_age_days: int = PICK_MAX_AGE_DAYS) -> tuple:
    """Return (kept, removed_count), dropping picks older than max_age_days
    trading days (see _pick_in_feed_window).

    Age is measured from each pick's ``date`` field (YYYY-MM-DD). Picks with a
    missing or unparseable date are kept — we can't safely age them out. Picks
    we have already bought are kept forever: expiry exists to clear the
    *available* list, and deleting a bought pick silently wipes the Purchased
    tab and the account-coverage history that goes with it.

    `max_age_days` is never below the largest age the mirror can be set to
    (MIRROR_AGE_CHOICES): pruning a pick the mirror is still allowed to buy
    loses it before the mirror's own gate ever says no.
    """
    today = _mirror_today()
    max_age_days = max(int(max_age_days), MIRROR_AGE_CHOICES[-1])
    # Any confirmed buy exempts a pick from expiry — a partially covered pick
    # is an open position we still owe brokers on, not a stale alert.
    purchased = _touched_pick_keys(picks)
    kept: List[Dict[str, str]] = []
    removed = 0
    for p in picks:
        raw = p.get("date")
        if (str(p.get("symbol") or "").upper(), str(raw)) in purchased:
            kept.append(p)  # bought — never expires
        elif _pick_in_feed_window(p, max_age_days, today):
            kept.append(p)  # undated, young enough, or before its last day
        else:
            removed += 1
    return kept, removed


def _pick_is_fresh(pick: Dict[str, str],
                   max_age_days: int = PICK_MAX_AGE_DAYS) -> bool:
    """True while a pick is still inside the feed's window — the same test
    _prune_stale_picks keeps on, so "still in the feed" means what it says.

    Undated picks count as fresh, matching _prune_stale_picks — we can't age
    out what we can't date, and dropping them silently would be worse than
    considering them.
    """
    return _pick_in_feed_window(pick, max(int(max_age_days), MIRROR_AGE_CHOICES[-1]),
                                _mirror_today())


def _mirror_today() -> date:
    """Today in New York — the calendar mirror's age gate counts in."""
    now = market_calendar.now_et()
    return now.date() if now is not None else date.today()


def _pick_trading_age(pick: Dict[str, str],
                      today: Optional[date] = None) -> Optional[int]:
    """Sessions since the alert (see market_calendar.trading_days_since), or
    None for an undated pick."""
    try:
        pd = datetime.strptime(str(pick.get("date")), "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None
    return market_calendar.trading_days_since(pd, today or _mirror_today())


def _pick_fresh_trading(pick: Dict[str, str], max_age: int,
                        today: Optional[date] = None) -> bool:
    """True while a pick is within `max_age` TRADING days of its alert.

    Calendar days killed Friday alerts on Monday: three days old by the
    calendar, one session by the market. Undated picks count as fresh, as in
    _pick_is_fresh.

    When the alert named its last day to buy (`last_buy`, see rsa_feed.to_pick)
    that date wins in both directions: BTOC posted after Friday's close with a
    last buy of the following Wednesday is still owed on Wednesday whatever the
    age limit says, and a play past its last day is shut however young it is.
    """
    today = today or _mirror_today()
    try:
        last = datetime.strptime(str(pick.get("last_buy") or "")[:10], "%Y-%m-%d").date()
    except (ValueError, TypeError):
        last = None
    age = _pick_trading_age(pick, today)
    if last is not None:
        # Capped, so a mistyped year on the last-day field can't keep a dead
        # play buyable for months.
        return today <= last and (age is None or age <= MIRROR_LAST_BUY_MAX_AGE)
    return age is None or age <= max_age



# ---------------------------------------------------------------------------
# Pick details: what the Command Center row says under the ticker.
#
# Display only. Nothing here decides what is bought or when: the mirror gates
# on _pick_fresh_trading and the note, and the extra fields below never reach
# either. Every helper returns "" / None for a field it can't read, so a
# malformed alert shows less, never a traceback in the middle of a redraw.
# ---------------------------------------------------------------------------

#: The operator machine's local copy of the whole feed (see feed_archive.py).
#: Read only, to fill in a pick stored before picks carried these fields; a
#: customer's copy has no archive and gets the same keys from the feed.
FEED_ARCHIVE_FILE = ROOT_DIR / "feed_archive.json"

#: Optional display keys a pick may carry beside symbol/note/date (see
#: rsa_feed.to_pick). Never part of any key: mirror keys stay (date, symbol).
PICK_DISPLAY_EXTRAS = ("ratio", "entry_price", "est_profit", "roundup_history",
                       "posted_at")

_ARCHIVE_INDEX: Dict[str, Any] = {"stamp": None, "by_key": {}, "dates": {}}


def _feed_archive_stamp() -> tuple:
    try:
        st = FEED_ARCHIVE_FILE.stat()
        return (str(FEED_ARCHIVE_FILE), st.st_mtime_ns, st.st_size)
    except (OSError, ValueError):
        return (str(FEED_ARCHIVE_FILE), None, None)


def _feed_archive_index() -> tuple:
    """(by_key, dates) from the local feed archive, rebuilt only when the file
    changes. by_key maps (SYMBOL, YYYY-MM-DD) to that alert's display fields;
    dates maps SYMBOL to every alert date the archive holds for it."""
    stamp = _feed_archive_stamp()
    if _ARCHIVE_INDEX["stamp"] == stamp:
        return _ARCHIVE_INDEX["by_key"], _ARCHIVE_INDEX["dates"]
    by_key: Dict[tuple, Dict[str, Any]] = {}
    dates: Dict[str, set] = {}
    rows: list = []
    if stamp[1] is not None:
        try:
            raw = json.loads(FEED_ARCHIVE_FILE.read_text(encoding="utf-8-sig"))
            buys = raw.get("buys") if isinstance(raw, dict) else None
            if isinstance(buys, dict):
                rows = list(buys.values())
            elif isinstance(buys, list):
                rows = buys
        except Exception:
            rows = []
    # Oldest post first, so a re-post of the same alert fills in what the
    # first copy left blank without blanking what it had.
    rows = [r for r in rows if isinstance(r, dict)]
    rows.sort(key=lambda r: str(r.get("posted_at") or ""))
    for r in rows:
        sym = str(r.get("symbol") or "").strip().upper()
        day = str(r.get("alert_date") or "").strip()[:10]
        if not sym or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", day):
            continue
        dates.setdefault(sym, set()).add(day)
        rec = by_key.setdefault((sym, day), {})
        lb = str(r.get("last_buy_date") or "").strip()[:10]
        if lb:
            rec["last_buy"] = lb
        for k in PICK_DISPLAY_EXTRAS:
            v = r.get(k)
            if v not in (None, ""):
                rec[k] = v
            elif k in r:
                rec.setdefault(k, "")
    _ARCHIVE_INDEX.update(stamp=stamp, by_key=by_key, dates=dates)
    return by_key, dates


def _parse_day(value: Any) -> Optional[date]:
    try:
        return datetime.strptime(str(value or "").strip()[:10], "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None


def _num(value: Any) -> Optional[float]:
    """A finite number from a stored field, or None."""
    if isinstance(value, bool) or value is None:
        return None
    try:
        f = float(str(value).replace("$", "").replace(",", "").strip())
    except (TypeError, ValueError):
        return None
    return f if f == f and abs(f) != float("inf") else None


def _fmt_short_day(d: Optional[date]) -> str:
    """'Fri 10/9'."""
    return f"{d:%a} {d.month}/{d.day}" if isinstance(d, date) else ""


def _fmt_md(d: Optional[date]) -> str:
    """'8/26'."""
    return f"{d.month}/{d.day}" if isinstance(d, date) else ""


def _trading_days_left(last: date, today: date) -> int:
    """Sessions still open to buy in: trading days from today through the
    last day, both counted. Bounded, like trading_days_since."""
    n = 0
    d = today
    for _ in range(120):
        if d > last:
            break
        if market_calendar.is_trading_day(d):
            n += 1
        d += timedelta(days=1)
    return n


def _last_day_urgency(last: Optional[date], today: Optional[date]) -> tuple:
    """(text, colour) for how long a pick stays buyable, or ("", "") when the
    alert named no last day."""
    if not isinstance(last, date) or not isinstance(today, date):
        return ("", "")
    if last < today:
        return ("closed", TEXT_MUTED)
    n = _trading_days_left(last, today)
    if n <= 0:
        return ("closed", TEXT_MUTED)   # last day falls on a closed day, none left
    if last == today:
        return ("today", YELLOW)
    return (f"{n} trading day{'s' if n != 1 else ''} left",
            YELLOW if n <= 1 else TEXT_SECONDARY)


def _fmt_price(value: Any) -> str:
    """'$0.2151' under a dollar, '$3.51' above it, '' when unreadable."""
    x = _num(value)
    if x is None or x <= 0:
        return ""
    if x < 0.01:
        return "$" + f"{x:.6f}".rstrip("0")
    if x < 1:
        return f"${x:.4f}"
    return f"${x:,.2f}"


def _fmt_est(value: Any) -> str:
    """'est +$3.23/acct'."""
    x = _num(value)
    if x is None:
        return ""
    return f"est {'+' if x >= 0 else '-'}${abs(x):,.2f}/acct"


def _fmt_ratio(value: Any) -> str:
    """'1:16' from '1:16' / '1-for-16' / '1 for 16'; '' when it isn't one."""
    m = re.search(r"1\s*(?::|-?\s*for\s*-?|/)\s*(\d{1,5})", str(value or ""), re.I)
    if not m or int(m.group(1)) < 2:
        return ""
    return f"1:{int(m.group(1))}"


def _history_style(history: Any) -> tuple:
    """(text, colour) for the feed's round-up history blurb: GREEN when it
    usually rounds up, YELLOW in between, RED at 0%, a muted 'no history' for
    N/A or blank."""
    text = str(history or "").strip()
    if not text or text.upper() in ("N/A", "NA", "NONE", "-"):
        return ("no history", TEXT_MUTED)
    m = re.search(r"(\d{1,3}(?:\.\d+)?)\s*%", text)
    if not m:
        return (text[:40], TEXT_SECONDARY)
    pct = float(m.group(1))
    return (text[:40], GREEN if pct >= 75 else (RED if pct <= 0 else YELLOW))


def _pick_details(pick: Dict[str, Any],
                  archive: Optional[Dict[tuple, Dict[str, Any]]] = None) -> Dict[str, Any]:
    """A pick's display fields: its own values first, the feed archive's for
    whatever it lacks. Every value is parsed or empty; never raises."""
    try:
        sym = str(pick.get("symbol") or "").strip().upper()
        day = str(pick.get("date") or "").strip()[:10]
        rec = (archive or {}).get((sym, day)) or {}

        def val(key):
            v = pick.get(key)
            return v if v not in (None, "") else rec.get(key)
        return {
            "alert": _parse_day(day),
            "last_buy": _parse_day(val("last_buy")),
            "ratio": _fmt_ratio(val("ratio")),
            "entry_price": _num(val("entry_price")),
            "est_profit": _num(val("est_profit")),
            "history": str(val("roundup_history") or "").strip()[:60],
            # Only a pick that came from a full alert can say "no history";
            # a hand-entered three-key row just says nothing.
            "has_history": "roundup_history" in pick or "roundup_history" in rec,
        }
    except Exception:
        return {"alert": None, "last_buy": None, "ratio": "", "entry_price": None,
                "est_profit": None, "history": "", "has_history": False}


def _fit_parts(parts: List[tuple], max_w: float, measure) -> List[tuple]:
    """Cut a run of (text, font, colour) parts to `max_w` pixels, ending in an
    ellipsis rather than running into whatever is drawn to its right."""
    out: List[tuple] = []
    if max_w <= 0:
        return out
    used = 0.0
    ell = "…"
    for text, spec, fill in parts:
        if not text:
            continue
        w = measure(text, spec)
        if used + w <= max_w:
            out.append((text, spec, fill))
            used += w
            continue
        room = max_w - used - measure(ell, spec)
        cut = text
        while cut and measure(cut, spec) > room:
            cut = cut[:-1]
        cut = cut.rstrip(" ·")
        if cut:
            out.append((cut + ell, spec, fill))
        elif out:
            # No room for even a letter of this part: end the previous one
            # with the ellipsis instead, still inside the limit.
            t, s, f = out.pop()
            used -= measure(t, s)
            room = max_w - used - measure(ell, s)
            while t and measure(t, s) > room:
                t = t[:-1]
            t = t.rstrip(" ·")
            if t:
                out.append((t + ell, s, f))
        break
    return out


def _carry_pick_extras(rows: List[Dict[str, Any]],
                       donors: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Fill the display-only extras a row lacks from a donor with the same
    (date, SYMBOL), so a feed copy without them doesn't wipe what the local
    cache already knew. Never touches symbol, note, date or last_buy."""
    try:
        by_key = {(str(p.get("date") or ""), str(p.get("symbol") or "").upper()): p
                  for p in donors or [] if isinstance(p, dict)}
        out = []
        for p in rows:
            d = by_key.get((str(p.get("date") or ""), str(p.get("symbol") or "").upper()))
            if d is not None and d is not p:
                missing = {k: d[k] for k in PICK_DISPLAY_EXTRAS
                           if k not in p and d.get(k) not in (None, "")}
                if missing:
                    p = {**p, **missing}
            out.append(p)
        return out
    except Exception:
        return rows


def _pick_key(p: Dict[str, str]) -> tuple:
    """(date, SYMBOL): one play, however many posts and copies it has."""
    return (str(p.get("date") or "").strip(), str(p.get("symbol") or "").strip().upper())


def _pick_posted(p: Dict[str, str]) -> Optional[datetime]:
    """When the alert behind `p` was posted (rsa_feed.to_pick's posted_at, or
    the cloud feed's), as an aware datetime; None when it isn't known."""
    text = str((p or {}).get("posted_at") or "").strip()
    if not text:
        return None
    try:
        when = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    return when if when.tzinfo is not None else when.replace(tzinfo=timezone.utc)


def _pick_later_post(new: Dict[str, str], old: Dict[str, str]) -> Optional[bool]:
    """True/False when both rows are dated and differ; None when the times
    can't say which post came last."""
    a, b = _pick_posted(new), _pick_posted(old)
    if a is None or b is None or a == b:
        return None
    return a > b


def _merge_picks(*lists: List[Dict[str, str]]) -> List[Dict[str, str]]:
    """Union of pick lists on (date, SYMBOL), earlier lists winning on conflict.

    One row per play. A key seen twice (the cloud feed can serve a play under
    both its message row and a picks.json row) keeps the later POST when both
    rows say when they were posted; otherwise the first row wins, as before.
    """
    merged: List[Dict[str, str]] = []
    at: Dict[tuple, int] = {}
    for picks in lists:
        for p in picks or []:
            key = _pick_key(p)
            i = at.get(key)
            if i is None:
                at[key] = len(merged)
                merged.append(p)
            elif _pick_later_post(p, merged[i]):
                merged[i] = p
    merged.sort(key=lambda p: str(p.get("date") or ""))
    return merged


def _pick_actionable(p: Dict[str, str]) -> bool:
    return str(p.get("note", "")).lower() in MIRROR_NOTES


def _prefer_actionable(merged: List[Dict[str, str]],
                       candidates: List[Dict[str, str]]) -> List[Dict[str, str]]:
    """`merged`, with a row replaced by the local candidate for the same
    (date, SYMBOL) when that candidate is the better answer.

    The alert channel posts a CONDITIONAL first and upgrades it to STANDARD
    when the split is declared, same symbol, same alert date. Dedupe on
    (date, SYMBOL) kept whichever row came first, so the upgrade was thrown
    away and mirror skipped a play it should have bought.

    The later post wins whenever both rows are dated -- in either direction:
    a STANDARD later CANCELLED (or re-posted conditional) is held, and the
    hold is what this copy keeps (see _import_picks_from_messages). Undated:
    a local hold stands against a copy that can't show it is newer, and an
    actionable candidate upgrades a non-actionable row only when the row
    isn't the one that is dated -- fail closed, a stale local Reg Alert must
    never re-arm a play the feed has since held.
    """
    cand = {_pick_key(p): p for p in candidates or []}
    if not cand:
        return merged
    out: List[Dict[str, str]] = []
    for p in merged:
        c = cand.get(_pick_key(p))
        if c is None or c is p or _pick_actionable(c) == _pick_actionable(p):
            out.append(p)            # the same answer either way: the feed's row
            continue
        later = _pick_later_post(c, p)
        if later is not None:
            out.append(c if later else p)
        elif c.get("held") and _pick_actionable(p):
            out.append(c)
        elif (_pick_actionable(c) and not _pick_actionable(p) and not p.get("held")
              and not (_pick_posted(p) is not None and _pick_posted(c) is None)):
            out.append(c)
        else:
            out.append(p)
    return out


def _local_picks() -> List[Dict[str, str]]:
    """Whatever is in the local cache right now, unpruned. [] if unreadable."""
    if PICKS_FILE.exists():
        data = atomic.load_state(PICKS_FILE, [])
        if isinstance(data, list):
            return data
    return []


# Serialises every read-merge-write of picks.json: a feed refresh
# (_fetch_quick_picks) and an alert import (_import_picks_from_messages ->
# _persist_picks) each read the file, merge, and write it back. Unlocked, the
# one that wrote second erased whatever the other had just added. Re-entrant:
# an import with nothing rendered yet refreshes from inside its own hold.
_PICKS_LOCK = threading.RLock()

# Per thread: whether the last _fetch_quick_picks on THIS thread got an answer
# from the cloud feed (True when there is no cloud to ask). None = not known.
_PICKS_FETCH = threading.local()


def _picks_fetch_failed() -> bool:
    """True when this thread's last _fetch_quick_picks fell back to the cache
    because the cloud feed couldn't be read."""
    return getattr(_PICKS_FETCH, "ok", None) is False


def _local_picks_age_s() -> Optional[float]:
    """Seconds since picks.json was last written, or None if it can't be read."""
    try:
        return max(0.0, datetime.now().timestamp() - PICKS_FILE.stat().st_mtime)
    except (OSError, ValueError):
        return None


# Set when the feed refused us for want of a board password, cleared on any
# successful read. Module-level because _cloud_picks() is a plain function that
# the App instance calls, not a method.
_PICKS_AUTH_ERROR: Optional[str] = None
# Whether the LAST _cloud_picks() call actually got an answer. A network error
# returns None without touching _PICKS_AUTH_ERROR, so that alone read an
# offline pull as a good one: the status bar said "just now" and the 5-30 min
# retry never scheduled.
_PICKS_LAST_FETCH_OK: bool = False


def _cloud_picks() -> Optional[List[Dict[str, str]]]:
    """Open plays from the cloud feed, or None if this copy couldn't read it.

    No account required. An unlinked install reads the open feed (see
    CloudSync._get), which is what lets a fresh checkout show plays on its very
    first launch instead of an empty screen.

    None and [] mean different things here: None is "no answer, keep what you
    have", [] is "the feed says nothing is open". Collapsing them would blank a
    customer's Quick Picks every time their wifi dropped.
    """
    global _PICKS_AUTH_ERROR, _PICKS_LAST_FETCH_OK
    _PICKS_LAST_FETCH_OK = False
    if not CLOUD_AVAILABLE:
        return None
    try:
        picks = cloud_sync.CloudSync().fetch_picks()
    except cloud_sync.CloudAuthError as exc:
        # Still None — the cache is right to survive this. But remember WHY, so
        # the empty state can say "paste your password" instead of "sit tight".
        _PICKS_AUTH_ERROR = str(exc)
        return None
    except Exception:
        return None          # CloudError, or anything the transport threw
    _PICKS_AUTH_ERROR = None
    if not isinstance(picks, list):
        return None
    _PICKS_LAST_FETCH_OK = True
    return picks


def _feed_batch_with_holds(batch, held_keys):
    """`batch` with each unknown-type post that HELD a play (see
    _import_picks_from_messages) published as watch-only "conditional".

    Unknown types stay local otherwise (rsa_feed.FeedBatch.to_json). A hold
    has to reach the cloud, or every customer's copy keeps buying the play
    the alerter called off -- and it goes as "conditional", not "unknown",
    because an older server still coerces an unknown kind to "standard"
    (served as "Reg Alert": a buy at every customer). The newest post per
    play is what the server serves (playsfeed.picks_json)."""
    held = set(held_keys or ())
    if not held or not getattr(batch, "buys", None):
        return batch
    try:
        buys = [dataclasses.replace(b, kind="conditional")
                if b.kind == rsa_feed.UNKNOWN_KIND
                and (str(b.alert_date or ""), str(b.symbol or "").upper()) in held
                else b for b in batch.buys]
        return dataclasses.replace(batch, buys=buys)
    except Exception:
        return batch


def _push_picks_remote(picks: List[Dict[str, str]]) -> bool:
    """Publish picks to the cloud feed. Operator-only; True if anything was sent.

    Only a machine holding RSAMAXXED_FEED_KEY can write the feed every
    subscriber reads. On a customer's copy this is a no-op that never touches
    the network — which is the point of the change: the build this replaced PUT
    the pick list to a public, keyless URL hard-coded in this file, so any copy
    of the app could rewrite or wipe everyone's picks, ours included.

    Ingest is insert-only and keyed on source_id, so re-publishing the same
    picks costs one round trip and changes nothing.
    """
    if not CLOUD_AVAILABLE or not picks:
        return False
    try:
        client = cloud_sync.CloudSync()
        if not client.can_publish_feed:
            return False
        buys = [b for b in (rsa_feed.from_pick(p) for p in picks) if b is not None]
        if not buys:
            return False
        client.publish_feed(rsa_feed.FeedBatch(buys=buys).to_json())
        return True
    except Exception:
        return False


def _fetch_quick_picks() -> List[Dict[str, str]]:
    """The live pick list: the cloud feed when this copy is linked, the local
    cache when it isn't.

    The feed decides what is *live*, but it can never delete history — a pick we
    have already bought is merged back in from the local cache. Without that, a
    play the server has aged out would silently take the Purchased tab and its
    account-coverage history with it, and those are open positions we still owe
    brokers on.

    Picks older than PICK_MAX_AGE_DAYS are pruned on load and the trimmed list
    written back to disk, which doubles as the offline cache.

    The network read happens first, OUTSIDE _PICKS_LOCK; the local file is
    read, merged and written back under it. Reading the file before the GET
    let an import that landed while the GET was in flight be written over by
    this refresh's stale merge -- the new pick gone, and the feed's last_id
    already past it, so it never came back.

    Whether the feed answered is left in _PICKS_FETCH.ok for the caller on
    this thread (see _picks_fetch_failed).
    """
    remote = _cloud_picks()
    _PICKS_FETCH.ok = remote is not None or not CLOUD_AVAILABLE
    with _PICKS_LOCK:
        return _merge_fetched_picks(remote)


def _merge_fetched_picks(remote: Optional[List[Dict[str, str]]]) -> List[Dict[str, str]]:
    """_fetch_quick_picks' merge and write, called holding _PICKS_LOCK."""
    local = _local_picks()
    local_bought = [p for p in local
                    if (str(p.get("symbol") or "").upper(), str(p.get("date") or ""))
                    in _touched_pick_keys(local)]

    # An EMPTY feed is never allowed to erase a populated cache. The server
    # stores the feed on a disk its host replaces on every deploy, so "no plays
    # at all" is far more often a wiped database than a genuinely quiet day —
    # and the old behaviour wrote that emptiness straight to disk, destroying
    # the only other copy the customer had. Keeping what we hold is safe in
    # both readings: if the feed really is empty, these picks age out on their
    # own within PICK_MAX_AGE_DAYS.
    if remote == [] and any(p for p in local if p not in local_bought):
        data, removed = _prune_stale_picks(local)
        if removed:
            try:
                _write_json(PICKS_FILE, data)
            except Exception:
                pass
        return data

    if remote is not None:
        # A pick imported on THIS machine from the alert channel reaches the
        # cloud feed only if this machine can publish, so a customer's
        # just-imported pick was missing from `remote` — and the merge below
        # dropped it and wrote picks.json without it, before mirror's
        # import-triggered check could buy it. Unbought local picks still
        # inside the feed's window are carried over; the remote copy wins,
        # except that a local Reg Alert upgrades a remote conditional of the
        # same (date, symbol), and a later local hold (a CANCELLED re-post)
        # stands over a remote Reg Alert — see _prefer_actionable.
        bought_keys = {(str(p.get("symbol") or "").upper(), str(p.get("date") or ""))
                       for p in local_bought}
        local_fresh = [p for p in local
                       if (str(p.get("symbol") or "").upper(), str(p.get("date") or ""))
                       not in bought_keys
                       and _pick_fresh_trading(p, PICK_MAX_AGE_DAYS)]
        data = _prefer_actionable(_merge_picks(remote, local_bought, local_fresh),
                                  local_fresh)
        # A feed that doesn't serve the display extras (ratio, price...) must
        # not erase the ones this cache already had. Display only.
        data = _carry_pick_extras(data, local)
        data, _ = _prune_stale_picks(data)
        try:
            _write_json(PICKS_FILE, data)
        except Exception:
            pass
        return data

    # No feed reachable — the local cache is all we have.
    data, removed = _prune_stale_picks(local)
    if removed:
        try:
            _write_json(PICKS_FILE, data)
        except Exception:
            pass
    return data


# ---------------------------------------------------------------------------
# Application
# ---------------------------------------------------------------------------

# Our own taskbar identity. Under pythonw the taskbar otherwise groups the
# window with Python and shows Python's icon instead of ours. Must be set before
# the Tk root exists, so it runs at import rather than in __init__.
if sys.platform == "win32":
    try:
        import ctypes as _ctypes
        _ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("RSAMAXXED.Terminal")
    except Exception:
        pass


class App(ctk.CTk):
    def __init__(self) -> None:
        super().__init__()
        # Before anything is built: every icon label reads ICON_FONT when it is
        # created, and the family list needs this root to exist. Windows 10
        # has no Segoe Fluent Icons, so without this every icon drew blank.
        # FONT_MONO the same way: Cascadia Code is missing on many machines.
        try:
            import tkinter.font as tkfont
            _families = tkfont.families(self)
            _select_icon_font(_families)
            _select_mono_font(_families)
        except Exception:
            pass
        # First, because the `after` override below reads it and a worker can
        # hand back work before the rest of __init__ has finished.
        self._ui_queue: "queue.Queue[tuple]" = queue.Queue()
        self._ui_pump_id: Optional[str] = None
        # Feed health, surfaced in the status bar and used to back off retries.
        self._feed_last_ok: Optional[datetime] = None
        self._feed_fail_streak: int = 0
        self._feed_retry_id: Optional[str] = None
        self.title(APP_WINDOW_TITLE)
        # Windows shows the default Python feather without this. Best-effort:
        # a missing icon must never stop the terminal from opening.
        try:
            ico = logo.ico_path()
            if ico:
                # default= covers every Toplevel (dialogs, the 2FA prompt) too.
                self.iconbitmap(default=ico)
                # CustomTkinter re-sets its own icon ~200ms after init on
                # Windows; re-assert ours once that has happened.
                self.after(250, lambda: self.iconbitmap(default=ico))
        except Exception:
            pass
        self.geometry("1480x900")
        self.configure(fg_color=BG_PRIMARY)
        self.minsize(1240, 780)

        # ---- runtime state ----
        self._log_lines: List[tuple] = []
        # Execution / live-activity state (Activity page + double-submit guard)
        self._trade_in_flight: bool = False   # ANY batch is running (automation gate)
        # Which brokers are mid-order right now. The desk guards on THIS, not on
        # _trade_in_flight: selling AIFA at Fidelity and BBBB at Robinhood at the
        # same time is two independent sessions and perfectly safe, while a second
        # order at a broker already working is the duplicate that must be refused.
        self._brokers_in_flight: set = set()
        # Mirror holds its first launch until both are True: the startup
        # session restore has finished (_startup_sessions_settled) and the
        # saved mirror state has been resumed (_mirror_resume). See
        # _mirror_startup_hold.
        self._startup_sessions_done = False
        self._mirror_resumed = False
        self._startup_began_at = datetime.now()
        # Last sign of life from whatever holds the gate: a batch starting, or
        # a broker reporting its leg. The sell queue's stall watchdog measures
        # from HERE rather than from when it started waiting, so a long healthy
        # trade is never mistaken for a wedged one.
        self._trade_progress_at: Optional[datetime] = None
        self._live_batches: List[dict] = []   # batches currently shown live
        self._live_anim_id: Optional[str] = None
        self._live_frame: int = 0
        self._active_nav: Optional[str] = None
        # Watchlist = RSA Quick Pick symbols (+ optional user-pinned extras).
        self._quick_picks: List[Dict[str, str]] = []
        self._user_watchlist: List[str] = _load_watchlist()
        self._pick_symbols: List[str] = []
        self._watchlist: List[str] = list(self._user_watchlist)
        self._quotes: Dict[str, Dict[str, Any]] = {}
        # Bumped on every quote merge. Pages fingerprint against it instead of
        # hashing the whole quote dict on every tab switch.
        self._quotes_rev: int = 0
        # Invest page. Initialised here, before _build_frames, because
        # _build_invest renders itself on the way up and reads all of it.
        # ETF quotes are kept apart from self._quotes: that cache is driven by
        # the RSA pick list and is rewritten every 45 seconds, which would
        # evict SPY the moment the picks changed.
        self._etf_quotes: Dict[str, Dict[str, Any]] = {}
        self._etf_exposure: str = etf_plan.EXPOSURES[0].key
        self._etf_tier: str = "low"          # the tier most accounts can reach
        self._etf_symbol: str = etf_plan.funds_in_tier("low")[0].symbol
        self._etf_auto = tk.BooleanVar(value=True)
        self._etf_fund = None
        self._etf_reco = None
        self._etf_history: Dict[str, List[float]] = {}
        self._etf_history_busy: set = set()
        self._etf_cash_status: Dict[str, tuple] = {}
        self._invest_expanded: set = set()   # brokers opened in the cash list
        self._invest_editing = None          # the one live cash Entry, if any
        # "max" by default: a fixed per-account figure has to be guessed, and
        # any guess is wrong for a fleet whose accounts hold anything from $20
        # to $250 -- a $100 default silently excluded most of them. Deploying
        # what is actually there needs no guess.
        self._etf_mode: str = "max"
        self._etf_target = tk.StringVar(value="100")
        self._etf_dry = tk.BooleanVar(value=False)
        self._etf_plan = None
        self._etf_quotes_busy: bool = False
        self._etf_cash_busy: bool = False
        # Counts ETF batches out and back — an invest run can be more than one.
        self._invest_in_flight: int = 0
        # Last-rendered fingerprint per page — see _page_signature.
        self._page_sig: Dict[str, Any] = {}
        # Drawn lists on hidden pages skip resize redraws until shown (see
        # RowCanvas). Only this app knows which page is on screen.
        RowCanvas.is_hidden = staticmethod(self._widget_hidden)
        self._notifications: List[Dict[str, Any]] = []
        self._notif_unread: int = 0
        self._notif_popup: Optional[tk.Toplevel] = None
        self._palette: Optional[tk.Toplevel] = None
        self._quote_loop_id: Optional[str] = None
        self._toasts: List[tk.Toplevel] = []
        # Round-up radar: open positions whose quote has exploded past our
        # recorded cost — the reverse split almost certainly executed.
        # Remembered across launches, so the same positions are not announced
        # again every time the app starts.
        self._roundup_flagged: set = _load_roundup_flagged()
        # TRACK board (the Exits page). Populated by the hourly poll; must exist
        # before _build_frames because the page renders from it on first build.
        self._track_rows: List[Any] = []
        self._track_error: str = ""
        self._track_pulled_at: str = ""
        self._track_busy: bool = False
        self._track_loop_id: Optional[str] = None
        self._exit_busy: bool = False   # a holdings read for an exit is running

        # Auto-sell. Restored from disk but ALWAYS re-armed deliberately in the
        # sense that matters: `sold` is what stops a restart re-selling a play
        # the previous run already closed. Built here, before _build_frames,
        # because the Exits page renders the toggles.
        _as = self._load_autosell_state()
        if self._autosell_state_blocked:
            # Unreadable record: off for the session, said once the log exists.
            self.after(1500, self._announce_autosell_state_blocked)
        # Every other state file that would not read (atomic.load_state):
        # said on screen, never read as empty and saved over.
        self._install_state_alerts()
        self._autosell_enabled = tk.BooleanVar(value=bool(_as.get("enabled")))
        self._autosell_dry_run = tk.BooleanVar(value=bool(_as.get("dry_run", True)))
        # Fractionals do NOT wait for an exit alert, and that is the point of
        # them — see _fractional_worklist. Defaults ON because it is how auto-
        # sell behaved before exits drove it, and switching the trigger over
        # must not quietly retire the other half of the job.
        self._autosell_fracs = tk.BooleanVar(value=bool(_as.get("fractionals", True)))
        # Closed plays ticked off, and whether we are peeking at them. The set
        # persists; the peek does not — a session should open on the tidy view
        # that was the point of confirming in the first place.
        self._confirmed_sells: set = _load_confirmed_sells()
        self._show_confirmed: bool = False
        # Claimed plays whose holdings read is still out and NO order has been
        # placed. Held in _autosell_sold too (so every "already handled" check
        # sees it) but written to disk separately — see _save_autosell_state.
        # One left over from the last session means that session died between
        # the claim and the order, so nothing was sold and it is released.
        self._autosell_reading: set = set()
        self._autosell_sold, self._autosell_released = _autosell_restore(_as)
        # Of those, the ones a DRY RUN claimed. Released when dry run is
        # switched off, so the first live run sells them — see
        # _release_dry_claims.
        self._autosell_dry_keys: set = {
            k for k in (_as.get("dry_sold") or [])
            if isinstance(k, str) and k in self._autosell_sold}
        # play -> brokerage -> when, for legs whose order may already be out.
        # Survives a narrowed key and a restart; see _autosell_holds.
        self._autosell_may_exist = _autosell_restore_holds(_as)
        self._autosell_may_exist_why = _autosell_restore_hold_reasons(_as)
        # key -> earliest time a handed-back play may be queued again. The
        # re-checks after buys and after the queue drains are minutes apart,
        # not an hour, so without this a broker that cannot log in would be
        # retried back to back.
        self._autosell_retry_after: Dict[str, datetime] = {}
        # Set when the pump starts work; a drained queue re-checks the board
        # only if it did something, so an empty check cannot loop.
        self._autosell_recheck: bool = False
        self._autosell_recheck_id: Optional[str] = None
        self._autosell_queue: List[Any] = []
        # A holdings read is out for the task the pump just popped. Covers the
        # window before _trade_in_flight goes up — see _autosell_pump.
        self._queue_busy: bool = False
        self._queue_busy_at: Optional[datetime] = None
        self._queue_held_said: bool = False
        self._queue_stalled_said: bool = False
        # The ONE pending pump tick. Every feeder calls the pump and the pump
        # re-arms itself, so without a single id to cancel, an hourly pull
        # landing mid-wait left two timer chains running and a sweep click a
        # third — see _pump_later.
        self._pump_after_id: Optional[str] = None
        # play key -> hand-backs so far.
        #
        # Persisted since 2026-10-10: a restart handed a broker that cannot log
        # in three fresh attempts, and the per-pull cap's hold-back likewise
        # let the next AUTOSELL_MAX_PER_PULL of a backlog through each launch.
        self._autosell_fails: Dict[str, int] = _autosell_restore_counts(_as)
        self._autosell_capped: set = {
            k for k in (_as.get("held_back") or []) if isinstance(k, str)}
        self._autosell_attn: Dict[str, Dict[str, str]] = _autosell_restore_attention(_as)

        self._configure_styles()
        self._build_shell()
        self._build_notification_bar()
        self._build_frames()
        # First paint of the two "N brokers linked" readouts. They are built
        # empty because the same call refreshes them later, when a broker is
        # linked from the Brokers page.
        self._render_linked_count()
        self._install_input_hook()
        self._install_shortcuts()
        self._show_frame("dashboard")
        # Draw the other pages behind the dashboard once the startup rush is
        # over, so the first visit to each is a raise, not a build.
        self.after(2500, self._prewarm_pages)

        self._tick_clock()
        # Drains work a background thread could not hand to Tk directly. Must be
        # running before the first worker starts — see `after` below.
        self.after(120, self._ui_pump)
        self.after(300, self._start_quote_loop)
        # Auto-refresh non-browser brokers on startup (browser brokers need manual bootstrap)
        self.after(700, self._startup_refresh)
        # TRACK board: runs on its own hourly timer, not the alert-feed toggle.
        self.after(2500, self._track_loop)
        # Mirror was armed when we last closed: bring it back, and say so. Late
        # enough that the activity log and the notification centre exist to
        # carry the announcement.
        self.after(3000, self._mirror_resume)
        # Library drift (a broker lib off its requirements.txt pin) breaks a
        # login with nothing but "Missing dependency". Checked off the main
        # thread once the log and notification centre exist; never blocks.
        self.after(1500, self._startup_depcheck)
        # No plays-password prompt on startup: the hosted feed is open, so a
        # fresh install has nothing to enter and asking would invent friction
        # that the product does not have. _prompt_plays_key stays reachable
        # from the picks screen for anyone pointed at a self-hosted deployment
        # that gates its own feed.

    # ---- Worker -> UI handoff ----------------------------------------------

    def after(self, ms, func=None, *args):
        """Tk's `after`, made safe to call from a worker thread.

        `_tkinter` lets a non-main thread register a callback only while the
        interpreter is actively dispatching; it waits about a second and then
        raises RuntimeError("main thread is not in main loop"). Startup renders
        for longer than that, so a worker that finished quickly — which is
        exactly what happens on a fresh install, where there are no cached picks
        to fetch and no quotes to look up — had its `after` call raise, and the
        exception killed the thread. The first pick render and the first quote
        refresh were dropped on the floor, leaving a new user staring at an
        empty Watchlist with nothing in the log to explain it.

        Rather than lose the update, hand it to a queue the main thread drains
        (`_ui_pump`). Ordering is preserved and the callback runs as soon as the
        event loop is free. Calls from the main thread take the normal path, so
        timers and their return ids behave exactly as before.
        """
        if threading.current_thread() is threading.main_thread():
            return super().after(ms, func, *args)
        try:
            return super().after(ms, func, *args)
        except RuntimeError:
            if callable(func):
                self._ui_queue.put((func, args))
            return None

    def _ui_pump(self) -> None:
        """Main-thread drain for work handed over by `after` above."""
        while True:
            try:
                func, args = self._ui_queue.get_nowait()
            except queue.Empty:
                break
            try:
                func(*args)
            except Exception as exc:      # one bad callback must not stop the pump
                self._log(f"UI update failed: {exc}", "warn")
        self._ui_pump_id = super().after(100, self._ui_pump)

    def _startup_depcheck(self) -> None:
        """Compare installed libraries against requirements.txt and, on a
        mismatch, say so loudly: an error notification plus an Activity line.

        Runs on a daemon thread so a slow metadata scan can never hold up the
        window; every step is guarded because a startup nicety must never be
        the thing that stops the app opening."""
        def _announce(msg: str) -> None:
            try:
                self._log(f"Dependency check: {msg}", "error")
            except Exception:
                pass
            try:
                self._push_notification(msg, "error")
            except Exception:
                pass

        def _work() -> None:
            try:
                from modules import depcheck
                depcheck.warn_at_startup(
                    lambda m: self.after(0, lambda m=m: _announce(m)))
            except Exception:
                pass

        try:
            threading.Thread(target=_work, name="depcheck", daemon=True).start()
        except Exception:
            pass

    # ---- Shell scaffolding ------------------------------------------------

    def _build_shell(self) -> None:
        """Global top command bar + live ticker tape + (sidebar | content)
        + bottom status bar."""
        self._build_topbar()
        self._build_ticker_tape()
        tk.Frame(self, bg=BORDER, height=1).pack(side="top", fill="x")
        self._build_statusbar()

        body = tk.Frame(self, bg=BG_PRIMARY)
        body.pack(side="top", fill="both", expand=True)
        self._build_sidebar(body)
        tk.Frame(body, bg=BORDER, width=1).pack(side="left", fill="y")
        self._build_content_area(body)

    def _build_statusbar(self) -> None:
        """Thin terminal-style status strip along the bottom edge."""
        bar = tk.Frame(self, bg=BG_SECONDARY, height=26)
        bar.pack(side="bottom", fill="x")
        bar.pack_propagate(False)
        tk.Frame(self, bg=BORDER, height=1).pack(side="bottom", fill="x")

        left = tk.Frame(bar, bg=BG_SECONDARY)
        left.pack(side="left", fill="y", padx=(16, 0))
        StatusDot(left, color=GREEN, size=6).pack(side="left", padx=(0, 6), pady=6)
        # Held on self: this counts what .env had at startup, and brokers get
        # linked later. Without a handle it could never be corrected.
        self._statusbar_conn_lbl = tk.Label(
            left, bg=BG_SECONDARY, fg=TEXT_MUTED,
            font=(FONT_FAMILY, 7, "bold"))
        self._statusbar_conn_lbl.pack(side="left")

        right = tk.Frame(bar, bg=BG_SECONDARY)
        right.pack(side="right", fill="y", padx=(0, 16))
        self._status_journal = tk.Label(right, text="", bg=BG_SECONDARY,
                                        fg=TEXT_MUTED, font=(FONT_MONO, 7))
        self._status_journal.pack(side="right", padx=(16, 0))
        self._status_quotes = tk.Label(right, text="QUOTES · AWAITING FIRST SYNC",
                                       bg=BG_SECONDARY, fg=TEXT_MUTED,
                                       font=(FONT_MONO, 7))
        self._status_quotes.pack(side="right", padx=(16, 0))
        # The plays are the product, so their freshness gets a permanent
        # readout. Quotes already had one and they matter far less.
        self._feed_status_lbl = tk.Label(right, text="FEED  ·  connecting…",
                                         bg=BG_SECONDARY, fg=TEXT_MUTED,
                                         font=(FONT_MONO, 7))
        self._feed_status_lbl.pack(side="right")

    # ---- Notification bar -------------------------------------------------

    def _build_notification_bar(self) -> None:
        """Alert bar that appears at top of content when a broker needs attention."""
        self._notif_bar = tk.Frame(self._content.master, bg=YELLOW, height=0)
        self._notif_label = tk.Label(self._notif_bar, text="", bg=YELLOW,
                                     fg=BG_PRIMARY, font=(FONT_FAMILY, 10, "bold"))
        self._notif_label.pack(padx=16, pady=6)
        self._notif_visible = False

    def _show_notification(self, message: str, color: str = YELLOW) -> None:
        """Show the notification bar with a message and play alert sound."""
        def _show():
            self._notif_bar.configure(bg=color)
            self._notif_label.configure(text=message, bg=color)
            if not self._notif_visible:
                self._notif_bar.pack(fill="x", padx=28, pady=(0, 4),
                                     before=self._content)
                self._notif_visible = True
            # flash the taskbar and play sound
            try:
                self.bell()
                winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
            except Exception:
                pass
            # bring window to front
            self.attributes("-topmost", True)
            self.after(500, lambda: self.attributes("-topmost", False))
        self.after(0, _show)

    def _hide_notification(self) -> None:
        def _hide():
            if self._notif_visible:
                self._notif_bar.pack_forget()
                self._notif_visible = False
        self.after(0, _hide)

    # ---- GUI input hook (replaces terminal input() for 2FA/OTP) -----------

    def destroy(self) -> None:
        """Record who closed the window.

        The app has been closing on its own mid-trade. Tk gives no hint whether
        that is the user, a stray teardown in this code, or the window manager,
        and `pyw` swallows anything printed. Whoever calls this gets their call
        stack written down first; after that the close proceeds untouched.
        """
        import traceback as _tb
        _crash_note("ROOT DESTROY", "".join(_tb.format_stack()))
        # The run log is written in the background (see mirror_journal); make
        # sure the last legs are on disk before the process can go away.
        try:
            mirror_journal.flush()
        except Exception:
            pass
        super().destroy()

    def report_callback_exception(self, exc, val, tb) -> None:
        """A raise inside a Tk callback must not take the window with it.

        tkinter's default hands the traceback to sys.stderr, which under `pyw`
        is nowhere — so a failing timer or button left the app half-updated
        with no sign anything had gone wrong, and any second failure inside
        that reporting path can end the event loop outright.

        Log it, say so on screen, and keep running. Losing one refresh is
        survivable; losing the window in the middle of a sell is not.
        """
        import traceback as _tb
        _crash_note("TK CALLBACK EXCEPTION",
                    "".join(_tb.format_exception(exc, val, tb)))
        try:
            self._push_notification(
                f"Internal error: {type(val).__name__}: {val} — see logs/crash.log",
                "error")
        except Exception:
            pass

    def _ask_inline(self, title: str, prompt: str, *,
                    show: Optional[str] = None,
                    timeout_s: Optional[float] = None,
                    dismiss: Optional[list] = None) -> Optional[str]:
        """Modal text prompt drawn INSIDE the main window.

        A tk popup is a separate OS window. Maximised, full-screen, or on a
        second monitor it can open behind the terminal or off to one side, and
        an unseen 2FA prompt is a login that dies on a code that expired while
        it sat there. This one is placed over the app itself, so it is on
        whichever screen the user is already looking at.

        Blocks on `wait_variable` — the same nested event loop `simpledialog`
        runs — so callers keep the ask-and-wait shape they already had.

        `timeout_s` takes the dialog down by itself, answering None: an
        unattended run must not keep a broker login (and every login queued
        behind its prompt) waiting on a box nobody is there to fill in.
        `dismiss`, a list, receives the cancel callback so a caller on another
        thread can take the dialog down too.
        """
        result: List[Optional[str]] = [None]
        done = tk.BooleanVar(self, value=False)

        overlay = tk.Frame(self, bg=BG_PRIMARY)
        overlay.place(relx=0, rely=0, relwidth=1, relheight=1)
        overlay.lift()

        card = RoundedFrame(overlay, bg_color=BG_CARD, border_color=ACCENT,
                            radius=RAD_MD)
        card.place(relx=0.5, rely=0.5, anchor="center")
        body = tk.Frame(card.inner, bg=BG_CARD)
        body.pack(padx=SP_2XL, pady=SP_2XL)

        tk.Label(body, text=title, bg=BG_CARD, fg=TEXT_PRIMARY,
                 font=(FONT_FAMILY, FS_H2, "bold")).pack(anchor="w")
        tk.Label(body, text=prompt, bg=BG_CARD, fg=TEXT_SECONDARY,
                 font=(FONT_FAMILY, 10), justify="left",
                 wraplength=460).pack(anchor="w", pady=(6, SP_LG))

        entry = ttk.Entry(body, width=32, font=(FONT_MONO, 13), justify="center",
                          **({"show": show} if show else {}))
        entry.pack(fill="x")

        def submit(_evt=None) -> None:
            result[0] = entry.get().strip()
            done.set(True)

        def cancel(_evt=None) -> None:
            result[0] = None
            done.set(True)

        btns = tk.Frame(body, bg=BG_CARD)
        btns.pack(fill="x", pady=(SP_LG, 0))
        PillButton(btns, text="Submit", bg_color=ACCENT, command=submit,
                   width=120, height=32).pack(side="right")
        PillButton(btns, text="Cancel", bg_color=BG_CARD_ALT, hover_color=RED,
                   command=cancel, width=100, height=32).pack(side="right",
                                                              padx=(0, SP_SM))

        entry.bind("<Return>", submit)
        entry.bind("<Escape>", cancel)
        overlay.bind("<Escape>", cancel)
        if dismiss is not None:
            dismiss[:] = [cancel]
        expire_id = None
        if timeout_s:
            def expire() -> None:
                if not done.get():
                    self._log(f"{title}: no answer in {int(float(timeout_s))}s — "
                              f"prompt dismissed", "warn")
                    cancel()
            expire_id = self.after(int(float(timeout_s) * 1000), expire)

        # focus after the widget is mapped, or the caret lands nowhere
        self.after(50, entry.focus_set)
        try:
            overlay.grab_set()
        except tk.TclError:
            pass
        self.wait_variable(done)
        if expire_id is not None:
            try:
                self.after_cancel(expire_id)
            except Exception:
                pass
        try:
            overlay.grab_release()
        except tk.TclError:
            pass
        overlay.destroy()
        return result[0]

    # ---- Full-window alert for "go do something on your phone" -------------

    def _show_action_alert(self, title: str, body: str, *,
                           detail: str = "", icon_name: str = "warning",
                           color: str = YELLOW,
                           waiting_text: str = "● waiting for approval",
                           raise_window: bool = True) -> None:
        """Full-window alert for a step only the user can complete elsewhere.

        `raise_window=False` is for a step done in a broker's browser window
        that has just been brought to the front: raising the app would bury
        the very window the user needs.

        Unlike `_ask_inline` there is nothing to type. A device approval is
        already sitting on the user's phone and the login is blocked until they
        tap it, so this takes no input, never grabs the keyboard, and stays up
        until the caller takes it down. It cannot be missed: it covers the whole
        window, raises the app, and beeps.

        Thread-safe — bootstrap runs on a worker thread.
        """
        def _show() -> None:
            existing = getattr(self, "_action_alert", None)
            if existing is not None and existing["frame"].winfo_exists():
                # Already showing: refresh the words rather than stacking a
                # second scrim on top of the first.
                existing["title"].configure(text=title)
                existing["body"].configure(text=body)
                existing["detail"].configure(text=detail)
                if existing.get("waiting") is not None:
                    existing["waiting"].configure(text=waiting_text)
                return

            overlay = tk.Frame(self, bg=BG_PRIMARY)
            overlay.place(relx=0, rely=0, relwidth=1, relheight=1)
            overlay.lift()

            card = RoundedFrame(overlay, bg_color=BG_CARD, border_color=color,
                                radius=RAD_LG)
            card.place(relx=0.5, rely=0.5, anchor="center")
            inner = tk.Frame(card.inner, bg=BG_CARD)
            inner.pack(padx=SP_3XL, pady=SP_3XL)

            tk.Label(inner, text=icon(icon_name), bg=BG_CARD, fg=color,
                     font=(ICON_FONT, 40)).pack(anchor="center")
            lbl_title = tk.Label(inner, text=title, bg=BG_CARD, fg=TEXT_PRIMARY,
                                 font=(FONT_FAMILY, FS_H1, "bold"),
                                 wraplength=520, justify="center")
            lbl_title.pack(anchor="center", pady=(SP_LG, SP_SM))
            lbl_body = tk.Label(inner, text=body, bg=BG_CARD, fg=TEXT_SECONDARY,
                                font=(FONT_FAMILY, 11), wraplength=520,
                                justify="center")
            lbl_body.pack(anchor="center")
            lbl_detail = tk.Label(inner, text=detail, bg=BG_CARD, fg=TEXT_MUTED,
                                  font=(FONT_FAMILY, 10), wraplength=520,
                                  justify="center")
            lbl_detail.pack(anchor="center", pady=(SP_LG, 0))

            waiting = tk.Label(inner, text=waiting_text, bg=BG_CARD,
                               fg=color, font=(FONT_MONO, 11))
            waiting.pack(anchor="center", pady=(SP_XL, 0))

            state = {"frame": overlay, "title": lbl_title, "body": lbl_body,
                     "detail": lbl_detail, "waiting": waiting, "pulse": None,
                     "on": True}

            def pulse() -> None:
                if not waiting.winfo_exists():
                    return
                state["on"] = not state["on"]
                waiting.configure(fg=color if state["on"] else TEXT_MUTED)
                state["pulse"] = self.after(650, pulse)

            pulse()

            # Dismissing hides the alert only. The login is still waiting on the
            # phone — saying otherwise would be a lie, and cancelling it here
            # would strand robin_stocks in its no-timeout poll.
            PillButton(inner, text="Hide this", bg_color=BG_CARD_ALT,
                       command=self._hide_action_alert,
                       width=140, height=34).pack(anchor="center", pady=(SP_XL, 0))

            self._action_alert = state

            if raise_window:
                try:
                    self.deiconify()
                    self.lift()
                    self.attributes("-topmost", True)
                    self.after(800, lambda: self.attributes("-topmost", False))
                except Exception:
                    pass
            try:
                self.bell()
                winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
            except Exception:
                pass

        self.after(0, _show)

    def _hide_action_alert(self) -> None:
        def _hide() -> None:
            state = getattr(self, "_action_alert", None)
            self._action_alert = None
            if state is None:
                return
            if state.get("pulse") is not None:
                try:
                    self.after_cancel(state["pulse"])
                except Exception:
                    pass
            try:
                if state["frame"].winfo_exists():
                    state["frame"].destroy()
            except Exception:
                pass

        self.after(0, _hide)

    def _arm_device_approval_alert(self, mod) -> Any:
        """Put a broker's device-approval push on screen while it blocks.

        Robinhood is the one that needs this: its re-login sends a push and then
        polls with no timeout, so a notification nobody sees is a bootstrap that
        hangs until the app is killed. Any broker module exposing
        `set_device_approval_hook` gets the same treatment; the rest are
        untouched. Returns the setter so the caller can unregister.
        """
        setter = getattr(mod, "set_device_approval_hook", None)
        if not callable(setter):
            return None
        broker_name = str(getattr(mod, "BROKER", "Broker")).capitalize()

        def _on_push(message: str) -> None:
            # Called from the login thread, mid-print. Everything here has to be
            # scheduled onto the UI loop.
            self.after(0, lambda: self._log(f"ALERT: {broker_name} — {message}"))
            self._show_action_alert(
                "Approve the login on your phone",
                message,
                detail=(
                    "Approve within about a minute — the login shares one "
                    "120-second budget between waiting for you and confirming "
                    "afterwards. Don't start another bootstrap while this is up: "
                    "repeated attempts trip Robinhood's rate limit, which then "
                    "fails with a misleading \"check credentials\" error."
                ),
                icon_name="lock",
            )

        try:
            setter(_on_push)
        except Exception:
            return None
        return setter

    def _disarm_device_approval_alert(self, setter) -> None:
        """Unregister the hook and take the alert down, however login ended."""
        if callable(setter):
            try:
                setter(None)
            except Exception:
                pass
        self._hide_action_alert()

    def _ask_from_thread(self, title: str, prompt: str,
                         timeout_s: Optional[float] = None) -> Optional[str]:
        """Put a question on screen from a worker thread and wait for it.

        Broker logins all run off the main thread, and `_ask_inline` can only
        be built on it, so the ask is marshalled across and the caller blocks
        on an Event until it comes back.

        `event.set()` is in a finally. Without it, ANY failure while building
        the dialog — a renamed widget kwarg, a Tk error mid-render — leaves the
        broker thread parked on `wait()` for the life of the process, holding a
        live browser session open on a 2FA page. A dialog that fails to draw
        must read as "no answer", not as a hang.

        Bounded by `timeout_s` for the same reason: the dialog dismisses itself
        on expiry, and if the UI loop never gets round to ours at all the wait
        gives up a little later anyway and the dialog is never shown.
        """
        result: List[Optional[str]] = [None]
        event = threading.Event()
        dismiss: list = []
        abandoned = threading.Event()

        def ask() -> None:
            try:
                if abandoned.is_set():
                    return                      # the asker gave up: show nothing
                self._show_notification(f"Action required: {prompt}", color=YELLOW)
                self._log(f"ALERT: {prompt}")
                result[0] = self._ask_inline(title, prompt, timeout_s=timeout_s,
                                             dismiss=dismiss)
                self._hide_notification()
            except Exception as exc:            # noqa: BLE001 — see docstring
                self._log(f"Could not show the {title.lower()} prompt: {exc}",
                          "error")
            finally:
                event.set()

        self.after(0, ask)
        if not timeout_s:
            event.wait()
            return result[0]
        # Grace past the dialog's own timer: a dialog that is up answers
        # through that. This only fires when the UI never ran ours.
        if not event.wait(float(timeout_s) + _ASK_GRACE_S):
            abandoned.set()

            def take_down() -> None:
                for cancel in list(dismiss):
                    try:
                        cancel()
                    except Exception:
                        pass
            try:
                self.after(0, take_down)
            except Exception:
                pass
            return None
        return result[0]

    def _install_input_hook(self) -> None:
        """Route broker 2FA/OTP asks to a dialog inside this window.

        TWO channels, because there are two kinds of caller.

        `_2fa_prompt.set_prompt_hook` is the real one: a broker module asks by
        name and gets an answer back. Nothing global is reassigned, so brokers
        bootstrapping side by side cannot tread on each other.

        The `builtins.input` patch stays for third-party code we do not own —
        robin_stocks asks for its MFA code by calling `input()` from inside its
        own `login()`, and there is no hook to register with it.

        The hook exists BECAUSE the builtins patch is not enough on its own.
        `builtins` is process-global: robinhood.py swaps `input` out twice
        during a bootstrap, and when a rehydrate overlapped a login the two
        restores interleaved and left robinhood's raising stub installed for
        the rest of the session. Fidelity then hit its OTP page, called
        `input()`, got a RuntimeError instead of a dialog, and reported "auth
        failed" nine seconds later — with the texted code still unused. Three
        logins in a row on 2026-09-02 died that way.
        """
        original_input = builtins.input

        def gui_input(prompt=""):
            # if called from main thread, use original (shouldn't happen)
            if threading.current_thread() is threading.main_thread():
                return original_input(prompt)
            # Bounded, and takes turns with the broker prompts (one dialog on
            # screen at a time). "" on expiry: no code, same as Cancel.
            answer = _2fa_prompt.run_exclusive(
                lambda: self._ask_from_thread("Broker Input Required",
                                              str(prompt).strip(),
                                              timeout_s=_GUI_INPUT_TIMEOUT_S),
                _GUI_INPUT_TIMEOUT_S)
            return answer if answer is not None else ""

        builtins.input = gui_input

        def otp_hook(broker: str, prompt: str, timeout_s: int) -> Optional[str]:
            if threading.current_thread() is threading.main_thread():
                # Nothing on the main thread should be blocking on a login, and
                # if one ever does, _ask_inline's nested loop can run inline.
                return self._ask_inline(f"{broker} verification", prompt,
                                        timeout_s=timeout_s)
            return self._ask_from_thread(f"{broker} verification", prompt,
                                         timeout_s=timeout_s)

        _2fa_prompt.set_prompt_hook(otp_hook)

        # Notices: a login waiting on something done in the broker's own
        # browser (SoFi's human check, a Chase code typed into the page). The
        # module has already brought that window to the front, so the alert
        # must not raise the app over it. Called from login threads.
        self._notice_broker: Optional[str] = None

        def notice_show(broker: str, title: str, message: str) -> None:
            def _on_ui() -> None:
                self._notice_broker = broker
                self._log(f"ALERT: {message}")
                self._push_notification(message, "warning")
            self.after(0, _on_ui)
            self._show_action_alert(
                title, message,
                detail=("The login is waiting on you and continues by itself "
                        "once that's done. If a browser window was opened for "
                        "it and you can't see it, look for it on the taskbar."),
                icon_name="lock", waiting_text="● waiting for you",
                raise_window=False,
            )

        def notice_clear(broker: str) -> None:
            def _on_ui() -> None:
                # Only take down this broker's notice -- not a Robinhood
                # approval or another broker's check that is still up.
                if self._notice_broker == broker:
                    self._notice_broker = None
                    self._hide_action_alert()
            self.after(0, _on_ui)

        _2fa_prompt.set_notice_hooks(notice_show, notice_clear)

    def _configure_styles(self) -> None:
        style = ttk.Style(self)
        style.theme_use("clam")

        style.configure(".", background=BG_PRIMARY, foreground=TEXT_PRIMARY,
                        fieldbackground=BG_INPUT, borderwidth=0)
        style.configure("TFrame", background=BG_PRIMARY)
        style.configure("TLabel", background=BG_PRIMARY, foreground=TEXT_PRIMARY)
        style.configure("Muted.TLabel", background=BG_PRIMARY, foreground=TEXT_SECONDARY)

        # Entry — flat field with a hairline that lights up on focus
        style.configure("TEntry", fieldbackground=BG_INPUT, foreground=TEXT_PRIMARY,
                        insertcolor=ACCENT, padding=9, borderwidth=1,
                        relief="flat", bordercolor=BORDER)
        style.map("TEntry",
                  fieldbackground=[("focus", BG_CARD_ALT)],
                  bordercolor=[("focus", ACCENT)],
                  lightcolor=[("focus", ACCENT)],
                  darkcolor=[("focus", ACCENT)])

        style.configure("TCombobox", fieldbackground=BG_INPUT, foreground=TEXT_PRIMARY,
                        padding=8, arrowcolor=TEXT_SECONDARY, borderwidth=1,
                        bordercolor=BORDER, relief="flat")
        style.map("TCombobox",
                  fieldbackground=[("readonly", BG_INPUT)],
                  bordercolor=[("focus", ACCENT)],
                  arrowcolor=[("active", TEXT_PRIMARY)])

        # Treeview — airier rows, quiet uppercase headers, pop-tinted selection
        style.configure("Treeview", background=BG_CARD, foreground=TEXT_PRIMARY,
                        fieldbackground=BG_CARD, rowheight=38,
                        font=(FONT_MONO, 11), borderwidth=0)
        style.configure("Treeview.Heading", background=BG_SECONDARY,
                        foreground=TEXT_MUTED,
                        font=(FONT_FAMILY, 9, "bold"), borderwidth=0,
                        relief="flat", padding=(10, 12))
        style.map("Treeview.Heading",
                  background=[("active", BG_CARD_ALT)],
                  foreground=[("active", TEXT_SECONDARY)])
        style.map("Treeview",
                  background=[("selected", ACCENT_SEL)],
                  foreground=[("selected", TEXT_PRIMARY)])
        style.layout("Treeview", [("Treeview.treearea", {"sticky": "nswe"})])

        # Slim, chromeless scrollbar
        style.configure("Vertical.TScrollbar", background=BORDER,
                        troughcolor=BG_CARD, arrowcolor=BG_CARD,
                        borderwidth=0, relief="flat", width=8,
                        arrowsize=0)
        style.map("Vertical.TScrollbar",
                  background=[("active", BORDER_LIGHT), ("pressed", ACCENT)])
        style.layout("Vertical.TScrollbar", [
            ("Vertical.Scrollbar.trough", {
                "children": [("Vertical.Scrollbar.thumb",
                              {"expand": "1", "sticky": "nswe"})],
                "sticky": "ns"})])

    # ---- Sidebar ----------------------------------------------------------

    # Ordered by the life of a play, not by category. A play arrives on the
    # Watchlist, gets opened on the Trade Desk (or by Mirror), and closes on
    # Exits — so the sidebar reads top to bottom in the order you actually
    # work. The old grouping split that in half: Watchlist lived under
    # OVERVIEW while Trade Desk and Exits lived under TRADING, which buried the
    # connection between them. (There was a Positions donut between Mirror and
    # Exits; it was removed — it only restated the journal, and Exits is where
    # an open play is acted on.)
    #
    # A section title of "" renders with no header — Command Center is the home
    # screen, not a member of a group.
    _NAV_SECTIONS = [
        ("", [
            ("dashboard", "Command Center", "dashboard"),
        ]),
        ("THE PLAY", [
            ("watchlist", "Watchlist", "watchlist"),      # what to open
            ("trade", "Trade Desk", "trade"),             # open it by hand
            ("mirror", "Mirror", "lightning"),            # or have it opened for you
            ("exits", "Exits", "export"),                 # close it
        ]),
        ("INVEST", [
            ("invest", "Invest", "pie"),          # what the profit does next
        ]),
        ("PERFORMANCE", [
            ("stats", "Analytics", "analytics"),
        ]),
        ("SETUP", [
            ("settings", "Automation", "automation"),
            ("accounts", "Brokers", "brokers"),
            ("logs", "Activity", "activity"),
        ]),
    ]

    def _build_sidebar(self, parent) -> None:
        self._sidebar = tk.Frame(parent, bg=SIDEBAR_BG, width=244)
        self._sidebar.pack(side="left", fill="y")
        self._sidebar.pack_propagate(False)

        self._nav_items: Dict[str, Dict[str, Any]] = {}
        tk.Frame(self._sidebar, bg=SIDEBAR_BG, height=12).pack(fill="x")

        for sect_title, items in self._NAV_SECTIONS:
            if sect_title:
                tk.Label(self._sidebar, text=sect_title, bg=SIDEBAR_BG, fg=TEXT_MUTED,
                         font=(FONT_FAMILY, 7, "bold")).pack(anchor="w", padx=26,
                                                             pady=(16, 6))
            else:
                tk.Frame(self._sidebar, bg=SIDEBAR_BG, height=6).pack(fill="x")
            for name, label, ic in items:
                self._make_nav_item(name, label, ic)

        tk.Frame(self._sidebar, bg=SIDEBAR_BG).pack(fill="both", expand=True)

        # footer: live connection status
        tk.Frame(self._sidebar, bg=BORDER, height=1).pack(fill="x", padx=18,
                                                          pady=(0, 12))
        foot = tk.Frame(self._sidebar, bg=SIDEBAR_BG)
        foot.pack(fill="x", padx=18, pady=(0, 16))
        self._sidebar_conn_dot = StatusDot(foot, color=GREEN, size=7)
        self._sidebar_conn_dot.pack(side="left", padx=(0, 7))
        self._sidebar_conn_lbl = tk.Label(
            foot, bg=SIDEBAR_BG, fg=TEXT_SECONDARY, font=(FONT_FAMILY, 8))
        self._sidebar_conn_lbl.pack(side="left")
        tk.Label(foot, text=f"v{APP_VERSION}", bg=SIDEBAR_BG, fg=TEXT_MUTED,
                 font=(FONT_MONO, 8)).pack(side="right")

    def _make_nav_item(self, name: str, label: str, ic: str) -> None:
        """Rounded pill nav item — CTk frame gives real anti-aliased corners."""
        item = ctk.CTkFrame(self._sidebar, corner_radius=10,
                            fg_color="transparent", bg_color=SIDEBAR_BG,
                            height=40)
        item.pack(fill="x", padx=14, pady=2)
        item.pack_propagate(False)
        icon_lbl = tk.Label(item, text=icon(ic), bg=SIDEBAR_BG, fg=TEXT_SECONDARY,
                            font=(ICON_FONT, 14), width=2, cursor="hand2")
        icon_lbl.pack(side="left", padx=(10, 0))
        text_lbl = tk.Label(item, text=f"  {label}", bg=SIDEBAR_BG,
                            fg=TEXT_SECONDARY, font=(FONT_FAMILY, 10, "bold"),
                            cursor="hand2")
        text_lbl.pack(side="left")
        dot = tk.Label(item, text="●", bg=SIDEBAR_BG, fg=SIDEBAR_BG,
                       font=(FONT_FAMILY, 6), cursor="hand2")
        dot.pack(side="right", padx=(0, 12))
        self._nav_items[name] = {
            "item": item, "icon": icon_lbl, "text": text_lbl, "dot": dot,
        }
        for widget in (item, icon_lbl, text_lbl, dot):
            widget.bind("<Enter>", lambda e, n=name: self._nav_hover(n, True))
            widget.bind("<Leave>", lambda e, n=name: self._nav_hover(n, False))
            widget.bind("<Button-1>", lambda e, n=name: self._show_frame(n))

    def _style_nav(self, name: str, state: str) -> None:
        """Apply 'idle' / 'hover' / 'active' visual state to a nav item."""
        refs = self._nav_items[name]
        if state == "active":
            fill, fg, icon_fg, dot = SIDEBAR_ACTIVE, TEXT_PRIMARY, ACCENT, ACCENT
        elif state == "hover":
            fill, fg, icon_fg, dot = SIDEBAR_HOVER, TEXT_PRIMARY, TEXT_PRIMARY, SIDEBAR_HOVER
        else:
            fill, fg, icon_fg, dot = None, TEXT_SECONDARY, TEXT_SECONDARY, SIDEBAR_BG
        refs["item"].configure(fg_color=fill if fill else "transparent")
        bg = fill if fill else SIDEBAR_BG
        refs["icon"].configure(bg=bg, fg=icon_fg)
        refs["text"].configure(bg=bg, fg=fg)
        refs["dot"].configure(bg=bg, fg=dot)

    def _nav_hover(self, name: str, entering: bool) -> None:
        if self._active_nav == name:
            return
        self._style_nav(name, "hover" if entering else "idle")

    def _set_active_nav(self, name: str) -> None:
        # Only the two items whose state actually changes. Each restyle is a
        # CTkFrame reconfigure — a canvas redraw — and doing all eleven on every
        # click was a visible stutter in the sidebar before the page even moved.
        prev = self._active_nav
        if prev != name and prev in self._nav_items:
            self._style_nav(prev, "idle")
        if name in self._nav_items:
            self._style_nav(name, "active")
        self._active_nav = name

    # ---- Content Area -----------------------------------------------------

    def _build_content_area(self, parent) -> None:
        wrapper = tk.Frame(parent, bg=BG_PRIMARY)
        wrapper.pack(side="left", fill="both", expand=True)
        # Header + page, frozen together on a swap so the title and the page
        # change in the same frame.
        self._content_wrap = wrapper

        # page header — icon + title + subtitle, with a right actions slot
        header = tk.Frame(wrapper, bg=BG_PRIMARY, height=70)
        header.pack(fill="x", padx=30, pady=(18, 0))
        header.pack_propagate(False)
        self._page_header = header

        title_row = tk.Frame(header, bg=BG_PRIMARY)
        title_row.pack(side="left", anchor="w", fill="y")
        self._page_icon = tk.Label(title_row, text=icon("dashboard"), bg=BG_PRIMARY,
                                   fg=ACCENT, font=(ICON_FONT, 20))
        self._page_icon.pack(side="left", anchor="n", pady=(3, 0))
        titles = tk.Frame(title_row, bg=BG_PRIMARY)
        titles.pack(side="left", padx=(13, 0))
        self._page_title = tk.Label(titles, text="Command Center", bg=BG_PRIMARY,
                                    fg=TEXT_PRIMARY, font=(FONT_FAMILY, FS_H1, "bold"))
        self._page_title.pack(anchor="w")
        self._page_subtitle = tk.Label(titles, text="", bg=BG_PRIMARY,
                                       fg=TEXT_SECONDARY, font=(FONT_FAMILY, 10))
        self._page_subtitle.pack(anchor="w", pady=(1, 0))

        self._header_right = tk.Frame(header, bg=BG_PRIMARY)
        self._header_right.pack(side="right", anchor="e", fill="y")

        tk.Frame(wrapper, bg=BORDER, height=1).pack(fill="x", padx=30, pady=(14, 0))
        self._content = tk.Frame(wrapper, bg=BG_PRIMARY)
        self._content.pack(fill="both", expand=True, padx=30, pady=16)

    def _build_frames(self) -> None:
        self._frames: Dict[str, tk.Frame] = {}
        self._build_dashboard()
        self._build_watchlist()
        self._build_trade()
        self._build_exits()
        self._build_invest()
        self._build_stats()
        self._build_settings()
        # After settings: the Mirror page reads the mirror state vars that
        # _build_settings creates (_mirror_enabled and friends).
        self._build_mirror()
        self._build_accounts()
        self._build_logs()
        # Every page is placed ONCE, stacked on top of each other, and a visit
        # just raises one. The old pack_forget/pack swap unmapped and remapped
        # a whole page tree per click, which is both slow and what made pages
        # visibly assemble: a remapped page is painted from scratch. Stacked
        # pages also keep their size while hidden, so a page can be rendered
        # BEHIND the current one and only raised once it is finished.
        for f in self._frames.values():
            f.place(in_=self._content, x=0, y=0, relwidth=1, relheight=1)

